window.MogiGramIdx={"e":[["〜あっての","あっての","〜があるからこそ成り立つ","~이 있기에 가능한, ~이 있고서야",["選手というのは、応援してくれるファン<b>あっての</b>存在だ。","ファン<b>あっての</b>プロ野球だということを忘れてはいけない。","お客様<b>あっての</b>商売だから、サービスには力を入れている。"],[18]],["あまりの〜に","あまりのに","とても〜なので","너무 ~한 나머지",["<b>あまりの</b>痛さ<b>に</b>、思わず声を上げてしまった。","<b>あまりの</b>暑さ<b>に</b>、食欲がなくなってしまった。"],[319]],["〜以外のなにものでもない","いがいのなにものでもない","まさに〜だ","~이외의 아무것도 아니다, 그야말로 ~이다",["約束を何度も破るなんて、裏切り<b>以外のなにものでもない</b>。","試合に負けたのは、練習不足<b>以外のなにものでもない</b>。","人の作品を自分の名前で発表するのは、盗作<b>以外のなにものでもない</b>。"],[150]],["いかに〜か","いかにか","どれほど〜か","얼마나 ~인지",["この映画を見て、家族が<b>いかに</b>大切<b>か</b>を改めて思わされた。","入院してみて、健康が<b>いかに</b>大切<b>か</b>がよくわかった。"],[320]],["〜いかんで（は）／〜いかんだ","いかんで","〜によって（決まる）","~여하에 따라(서는), ~에 달려 있다",["新しい計画が成功するかどうかは、社員の協力<b>いかんだ</b>。","検査の結果<b>いかんでは</b>、手術が必要になるかもしれない。","試験に合格できるかどうかは、これからの努力<b>いかんだ</b>。"],[19]],["〜いかんにかかわらず／〜いかんによらず／〜いかんを問わず","いかんにかかわらず","〜がどうであっても関係なく","~여하에 관계없이, ~여하를 불문하고",["年齢や国籍<b>のいかんによらず</b>、どなたでも参加できます。","国籍<b>のいかんを問わず</b>、能力のある人を採用する方針だ。","この大会には、経験の<b>いかんを問わず</b>誰でも参加できる。"],[23]],["いざ〜というときになって","いざというときになって","ちょうど〜する時になって","막상 ~하려는 때가 되어",["いざ発表<b>というとき</b>になって、資料がないことに気づいた。","<b>いざ</b>結婚<b>というときになって</b>、彼は急に不安になった。"],[321]],["いざ〜となると","いざとなると","実際に〜する時になると","막상 ~하게 되면",["いざ本番<b>となると</b>、緊張して言葉が出てこない。","留学したいと思っていたが、<b>いざ</b>行く<b>となると</b>不安になってきた。"],[322]],["〜以上（は）","いじょう","〜のだから（当然）","~한 이상(은)",["会社を辞めた<b>以上は</b>、自分の力で生きていくしかない。","引き受けた<b>以上</b>、最後まで責任を持ってやるつもりだ。","約束した<b>以上</b>、必ず守ります。"],[151]],["いっさい〜ない","いっさいない","まったく〜ない","일절 ~않다",["この料理には、化学調味料を<b>いっさい</b>使っていない。","当店では、お客様の個人情報を外部に<b>いっさい</b>提供しません。","この部屋での飲食は<b>いっさい</b>禁止されている。"],[194]],["今でこそ〜が","いまでこそが","今は〜だが、前は違った","지금이야 ~이지만",["<b>今でこそ</b>人気の店だが、開店当初は客がほとんど来なかった。","<b>今でこそ</b>笑って話せる<b>が</b>、当時は本当につらかった。"],[323]],["〜うえで","うえで","〜するときに・〜する場合に","~하는 데 있어서",["外国で暮らす<b>うえで</b>、言葉は何より大切だ。","留学する<b>うえで</b>、語学力は欠かせない。"],[195]],["〜うえに","うえに","〜だけでなく、さらに","~한 데다가",["今日は雨が降っている<b>うえに</b>、風も強い。","この部屋は駅から近い<b>うえに</b>、家賃も安い。"],[324]],["〜（よ）うが／〜（よ）うと（も）","うが","たとえ〜ても（関係ない）","~하든, ~하더라도",["どんなに優秀な選手<b>であろうと</b>、練習を怠れば勝てない。","平日<b>だろうが</b>休日<b>だろうが</b>、この店はいつも混んでいる。","人に<b>何と</b>思われ<b>ようと</b>、自分が正しいと思う道を進む。"],[6]],["〜（よ）うが〜まいが／〜（よ）うと〜まいと","うがまいが","〜しても、しなくても","~하든 말든",["周りが賛成<b>しようがしまいが</b>、自分の道は自分で決める。","雨が<b>降ろうと降るまいと</b>、試合は予定どおり行われる。","彼は人が<b>見ていようがいまいが</b>、いつも丁寧に仕事をする。"],[63]],["〜（よ）うではないか","うではないか","いっしょに〜しよう（呼びかけ）","~하지 않겠는가, ~합시다",["子どもたちの未来のために、今こそ行動しよう<b>ではないか</b>。","みんなで力を合わせて、この町をきれいにしよ<b>うではないか</b>。"],[325]],["〜（よ）うとする","うとする","〜しようと努力する・〜する直前だ","~하려고 하다",["彼には人の意見を聞こ<b>うとする</b>姿勢がまったくない。","電車に乗ろ<b>うとした</b>とき、ドアが閉まってしまった。"],[326]],["〜（よ）うにも〜ない","うにもない","〜しようとしても、できない","~하려야 ~할 수 없다",["電話番号がわからないので、連絡し<b>ようにも</b>でき<b>ない</b>。","財布を忘れてしまい、昼ご飯を<b>買おうにも買えない</b>。","電車が止まっていて、帰ろう<b>にも</b>帰れない。"],[50]],["〜（よ）うものなら","うものなら","もし〜したら（大変なことになる）","~하기라도 하면, ~했다가는",["祖母の前で食べ物を残そう<b>ものなら</b>、ひどく叱られる。","あの先生の授業に一分でも遅れ<b>ようものなら</b>、教室に入れてもらえない。","この道路は狭いので、雪でも降ろう<b>ものなら</b>、すぐに渋滞してしまう。"],[169]],["〜得る","うる","〜する可能性がある","~할 수 있다, ~할 가능성이 있다",["この計画では、予定どおりに進まないことも十分<b>あり得る</b>。","これは、だれにでも起こり<b>得る</b>問題だ。"],[327]],["〜おそれがある","おそれがある","〜という悪いことが起こるかもしれない","~할 우려가 있다",["失敗する<b>おそれがあるからといって</b>、何も挑戦しないのはもったいない。","台風が上陸する<b>おそれがある</b>。"],[234]],["〜かいがある／〜かいもなく","かいがある","〜した効果がある／効果もなく","~한 보람이 있다 / ~한 보람도 없이",["何度も書き直した<b>かいもなく</b>、企画は採用されなかった。","何度も説得した<b>かいもなく</b>、彼は会社を辞めてしまった。","毎日練習した<b>かいがあって</b>、試合に勝つことができた。"],[85]],["〜か否か","かいなか","〜かどうか","~인지 아닌지",["彼が本当のことを話している<b>か否か</b>、確かめる方法はない。","彼の申し出を受ける<b>べきか否か</b>、まだ決めかねている。","その計画を実行する<b>か否か</b>は、来週の会議で決まる。"],[64]],["〜か否かにかかわらず","かいなかにかかわらず","〜かどうかに関係なく","~인지 아닌지에 관계없이",["経験がある<b>か否かにかかわらず</b>、誰でも応募できます。","会員である<b>か否かにかかわらず</b>、どなたでも参加できます。"],[328]],["〜が思い出される","がおもいだされる","自然に〜を思い出す","~이 (저절로) 떠오르다",["この写真を見ると、学生時代のことが懐かしく<b>思い出される</b>。","秋になると、亡くなった祖母のこと<b>が思い出される</b>。"],[336]],["〜が欠かせない","がかかせない","〜がどうしても必要だ","~이 빠질 수 없다, ~이 꼭 필요하다",["健康な体を保つには、バランスのよい食事が<b>欠かせない</b>。","外国語の上達には、毎日の積み重ねが<b>欠かせない</b>。"],[239]],["〜限り","かぎり","〜の間はずっと・〜の範囲では","~하는 한",["体が元気な<b>かぎり</b>、この仕事を続けたい。","学生である<b>限り</b>、勉強を第一に考えるべきだ。"],[235]],["〜かぎりだ","かぎりだ","とても〜だ（気持ち）","~하기 그지없다, 너무나 ~하다",["憧れの先生に作品をほめてもらえて、うれしい<b>かぎりだ</b>。","若い人たちがこんなに活躍しているのは、頼もしい<b>限りだ</b>。","久しぶりに故郷の友人たちに会えて、うれしい<b>かぎりです</b>。"],[95]],["〜限りでは","かぎりでは","〜の範囲では","~한 바로는",["私が調べた<b>かぎりでは</b>、この本はもう絶版になっている。","私が調べた<b>限りでは</b>、この店は明治時代から続いているらしい。"],[236]],["〜かけたまま","かけたまま","〜している途中の状態で","~하다 만 채로",["弟は宿題をやり<b>かけたまま</b>、遊びに行ってしまった。","本を読み<b>かけたまま</b>、いつのまにか眠ってしまった。"],[329]],["〜かたがた","かたがた","〜を兼ねて","~을 겸해서, ~할 겸",["ご無沙汰のお詫び<b>かたがた</b>、近況をご報告いたします。","退院のご報告<b>かたがた</b>、お世話になった先生のお宅に伺った。","近くまで参りましたので、ご挨拶<b>かたがた</b>お邪魔いたしました。"],[65]],["AがAだけに","がだけに","Aが普通ではないので","~가 ~인 만큼",["<b>場所が場所だけに</b>、大きな声で話すわけにはいかない。","事<b>が</b>事<b>だけに</b>、慎重に対応しなければならない。","<b>相手が相手だけに</b>、油断はできない。"],[198]],["〜（の）かたわら","かたわら","〜をする一方で（別のこともする）","~하는 한편",["祖父は農業を営む<b>かたわら</b>、地域の歴史を研究している。","兄は大学で研究する<b>かたわら</b>、高校生に数学を教えている。","兄はレストランの経営<b>のかたわら</b>、料理教室も開いている。"],[86,214]],["〜がちな","がちな","〜しやすい・よく〜する（よくないこと）","~하기 쉬운, 자주 ~하는",["冬は運動不足になり<b>がちな</b>ので、毎日歩くようにしている。","彼は子どものころ、病気<b>がちな</b>子だった。"],[337]],["〜がてら","がてら","〜のついでに","~하는 김에, ~을 겸해서",["友人の引っ越しの手伝い<b>がてら</b>、新しい町を見て回った。","天気がいいので、運動<b>がてら</b>隣の町まで自転車で出かけた。","買い物<b>がてら</b>、駅前の新しいカフェに寄ってみた。"],[42]],["〜かというと（そうではない）","かというと","本当に〜かと考えると（そうでもない）","~인가 하면 (그렇지도 않다)",["彼が本当に反省している<b>かというと</b>、そうでもないらしい。","高い服がすべて品質がいい<b>かというと</b>、そうとも限らない。","なぜこの店を選んだ<b>かというと</b>、駅から近いからだ。"],[111]],["〜（た）かと思うと／〜（た）かと思ったら","かとおもうと","〜したすぐあとに（もう）","~하는가 싶더니, ~했나 했더니",["空が暗くなった<b>かと思うと</b>、急に大粒の雨が降り出した。","静かだから誰もいないの<b>かと思ったら</b>、みんな奥の部屋で寝ていた。","弟は泣いていた<b>かと思えば</b>、もう笑っている。"],[170]],["〜か〜ないかのうちに","かないかのうちに","〜するとほとんど同時に","~할까 말까 하는 사이에, ~하자마자",["布団に入る<b>か</b>入ら<b>ないかのうちに</b>、眠ってしまった。","終業のチャイムが鳴る<b>か鳴らないかのうちに</b>、学生たちは教室を出ていった。","彼は席に着く<b>か</b>着か<b>ないか</b>のうちに、もう話し始めた。"],[196]],["〜かねない","かねない","〜という悪い結果になるかもしれない","~할지도 모른다, ~할 수도 있다 (나쁜 결과)",["このまま無理を続けると、体を壊し<b>かねない</b>。","そんなにスピードを出したら、事故を起こし<b>かねない</b>。"],[330]],["〜かねる","かねる","〜するのは難しい・できない（ていねいに断る）","~하기 어렵다, ~할 수 없다",["そのご要望にはお応えし<b>かねます</b>ので、ご了承ください。","申し訳ございませんが、そのご質問にはお答えし<b>かねます</b>。","恐れ入りますが、こちらの商品の返品はお受けし<b>かねます</b>。"],[96]],["〜かのごとく／〜かのごとき","かのごとく","まるで〜かのように","마치 ~인 것처럼",["彼は何も知らない<b>かのごとく</b>、平然とした顔をしていた。","彼は<b>まるで</b>自分の家にいる<b>かのごとく</b>くつろいでいる。","彼はすべてを見てきた<b>かのごとき</b>口ぶりで事件について語った。"],[87]],["〜かのように","かのように","本当は違うが、まるで〜ように","마치 ~인 것처럼",["彼は何事もなかった<b>かのように</b>、笑顔で会議に戻ってきた。","まるで夢を見ている<b>かのような</b>気分だった。","彼はその場にいなかったのに、まるで自分の目で見た<b>かのように</b>話した。"],[152]],["〜が早いか","がはやいか","〜するとすぐに","~하자마자, ~하기가 무섭게",["彼女はベルが鳴る<b>が早いか</b>、教室を飛び出していった。","子どもたちはおやつを見る<b>が早いか</b>、一斉に手を伸ばした。","彼は給料をもらう<b>が早いか</b>、全部使ってしまった。"],[67]],["〜からある／〜からする／〜からの","からある","〜以上もある（多さを強調）","~이나 되는",["彼女は一着10万円<b>からする</b>ドレスを何着も持っている。","この湖には、体長1メートル<b>からある</b>魚がいるそうだ。","その祭りには、毎年10万人<b>からの</b>観光客が訪れる。"],[41]],["〜からこそ","からこそ","ほかの理由ではなく、〜だから","(바로) ~이기 때문에",["苦しい経験をした<b>からこそ</b>、人の痛みがわかるのだ。","あなたのことを大切に思う<b>からこそ</b>、厳しいことを言うのです。"],[332]],["〜からして","からして","〜一つを見ても（ほかももちろん）","~부터가",["彼の口ぶり<b>からして</b>、試験はうまくいったようだ。","あの店は店員の態度<b>からして</b>感じが悪い。"],[237]],["〜からすると／〜からすれば","からすると","〜から考えると","~으로 보아, ~로 판단하면",["今の売り上げ<b>からすれば</b>、目標の達成は難しいだろう。","空の様子<b>からすると</b>、午後から雨が降りそうだ。"],[197]],["〜からだ","からだ","〜が理由だ","~때문이다",["最近よく眠れない。仕事の悩みが頭から離れない<b>からだ</b>。","試験に落ちたのは、勉強が足りなかった<b>からだ</b>。"],[333]],["〜からであろう","からであろう","〜からだろう（書き言葉）","~때문일 것이다",["子どもたちが外で安心して遊べるのは、この町が安全<b>だからであろう</b>。","この店がいつも混んでいるのは、値段が安い<b>からであろう</b>。"],[334]],["〜からといって","からといって","〜という理由だけで（…とは言えない）","~라고 해서 (…인 것은 아니다)",["日本人だ<b>からといって</b>、敬語が正しく使える<b>とは限らない</b>。","子ども<b>だからといって</b>、何をしても許されるわけではない。","値段が高い<b>からといって</b>、品質がいいとは限らない。"],[127]],["〜からなる","からなる","〜で作られている・構成される","~(으)로 이루어지다",["市民と専門家<b>からなる</b>委員会が、計画の見直しを提案した。","この委員会は、10人の専門家<b>からなる</b>。","日本の国会は、衆議院と参議院の二つ<b>からなる</b>。"],[66]],["〜からには","からには","〜のだから、当然","~한 이상(에는)",["引き受けた<b>からには</b>、最後まで責任を持ってやり遂げる。","日本に来た<b>からには</b>、日本語をしっかり身に付けたい。","約束した<b>からには</b>、必ず守らなければならない。"],[171]],["〜からにほかならない","からにほかならない","まさに〜からだ","바로 ~때문이다, ~때문에 다름 아니다",["彼が成功したのは、努力を続けた<b>からにほかならない</b>。","親が子どもを叱るのは、子どもを愛している<b>からにほかならない</b>。"],[238]],["AかれBかれ","かれかれ","AでもBでも（どちらにしても）","~하든 ~하든 (遅かれ早かれ 조만간)",["<b>遅かれ早かれ</b>、本当のことはわかるだろう。","人はだれでも、<b>多かれ少なかれ</b>悩みを持っているものだ。"],[335]],["〜きっかけになれば（と思い）","きっかけになれば","〜のきっかけになってほしいと思って","~하는 계기가 되었으면 (해서)",["この本が、読書を好きになる<b>きっかけになれば</b>と思う。","この交流会が、お互いの国を知る<b>きっかけになれば</b>と思います。"],[339]],["〜きらいがある","きらいがある","〜という（よくない）傾向がある","~하는 (좋지 않은) 경향이 있다",["私は忙しくなると、食事をおろそかにする<b>きらいがある</b>。","日本の会社は、前例のないことを避ける<b>きらいがある</b>。","彼女は、人の話を最後まで聞かずに結論を出す<b>きらいがある</b>。"],[34]],["〜（た）きり","きり","〜したのが最後で、そのまま","~한 채 (그 후로는), ~한 것을 마지막으로",["弟は部屋に入った<b>きり</b>、夕食の時間になっても出てこない。","兄は朝早く出かけた<b>きり</b>、まだ帰ってこない。","友人に貸した本は、貸した<b>きり</b>戻ってこない。"],[172]],["〜きる","きる","全部〜する・最後まで〜する","다 ~하다, 끝까지 ~하다",["人気の限定ケーキは、開店からわずか一時間で売り<b>切れて</b>しまった。","父は長い小説を一晩で読み<b>きった</b>。"],[340]],["〜きれない","きれない","全部〜することができない","다 ~할 수 없다",["一度にこんなにたくさんの単語は、とても覚え<b>きれない</b>。","旅行では、写真に撮り<b>きれない</b>ほどの美しい景色を見た。","この量の宿題は、一日ではとてもやり<b>きれない</b>。"],[141]],["〜極まる／〜極まりない","きわまる","この上なく〜だ","~하기 짝이 없다",["何の連絡もなく約束をすっぽかすとは、失礼<b>極まりない</b>。","雪道をスピードを出して走るなんて、無謀<b>極まりない</b>。","人の話を最後まで聞かずに席を立つとは、失礼<b>極まりない</b>。"],[20]],["〜くせに","くせに","〜のに（非難）","~인 주제에, ~이면서",["自分は何も手伝い<b>もしないくせに</b>、文句だけは一人前だ。","自分では何もしない<b>くせに</b>、人のやり方には口を出す。"],[240]],["〜くらい","くらい","〜ほど（程度）","~정도, ~만큼",["それまでの悩みがうそに思える<b>くらい</b>、気分がすっきりした。","声がかれる<b>くらい</b>大きな声で応援した。","足が痛くて歩けない<b>くらい</b>疲れた。"],[199]],["〜くらい（ぐらい）で","くらいで","〜程度のことで","~정도로(는), ~쯤으로",["この問題は、一晩<b>くらいで</b>解決できる<b>ようなものではない</b>。","一度失敗した<b>くらいで</b>、あきらめてはいけない。"],[341]],["〜くらいなら","くらいなら","〜のような嫌なことをするより（…のほうがいい）","~할 바에는 (차라리)",["途中でやめる<b>くらいなら</b>、初めからやらないほうがいい。","あの人に謝る<b>くらいなら</b>、会社を辞めたほうがましだ。","あんな会社で働く<b>くらいなら</b>、アルバイトをしているほうがましだ。"],[128]],["〜ぐらいのことは","ぐらいのことは","少なくとも〜程度のことは","적어도 ~정도는",["遅れるのなら、電話を一本かける<b>ぐらいのことは</b>してもよかろう。","自分の部屋の掃除<b>ぐらいのことは</b>、自分でしなさい。"],[342]],["〜ぐらいのものだ","ぐらいのものだ","〜だけだ","~정도뿐이다",["最近、家族とゆっくり話すのは夕食のとき<b>ぐらいのものだ</b>。","毎朝五時に起きて走っているのは、この町では彼<b>ぐらいのものだ</b>。"],[241]],["〜傾向がある","けいこうがある","〜しやすい性質がある","~하는 경향이 있다",["最近の若者は、新聞よりもネットでニュースを読む<b>傾向がある</b>。","彼は物事を悪いほうに考える<b>傾向がある</b>。"],[343]],["決して〜ない","けっしてない","絶対に〜ない","결코 ~않다",["この計画は<b>決して</b>簡単だとは言え<b>ない</b>。","このご恩は<b>決して</b>忘れ<b>ません</b>。"],[344]],["〜現在","げんざい","〜の時点で","~현재",["5月1日<b>現在</b>の会員数は300人だ。","午前9時<b>現在</b>、台風は九州の南の海上にある。"],[345]],["〜こそ〜が","こそが","〜は…だが（別の点では）","~은 ~이지만, ~이야 ~이지만",["賞<b>こそ</b>取れなかったが、多くの人に作品を見てもらえた。","彼は口<b>こそ</b>悪い<b>が</b>、本当は優しい人だ。"],[346]],["〜こそすれ","こそすれ","〜はするが（その反対は決してない）","~하기는 해도 (결코 …않다), ~할지언정",["彼の努力には感心し<b>こそすれ</b>、非難する理由は何もない。","親の厳しさには感謝し<b>こそすれ</b>、恨んだことは一度もない。"],[242]],["〜こと＋数量","こと","〜する状態が（時間・回数）続いて","~하기를 (몇 시간·몇 번)",["待つ<b>こと</b>3時間、ようやく順番が回ってきた。","山道を歩く<b>こと</b>2時間、やっと頂上に着いた。"],[347]],["〜ことから","ことから","〜という理由・根拠で","~라는 점에서, ~때문에",["道路がぬれている<b>ことから</b>、夜のうちに雨が降ったとわかる。","この辺りは桜の木が多い<b>ことから</b>、「桜町」と呼ばれている。"],[348]],["〜ごとき／〜ごとく","ごとき","〜のような／〜のように","~와 같은 / ~와 같이",["<b>私ごとき</b>がこのような賞をいただいてよいのでしょうか。","ご存じの<b>ごとく</b>、当社は来年創立五十周年を迎えます。","私<b>のごとき</b>若輩者に、このような大役が務まるでしょうか。"],[75]],["〜ことだ","ことだ","〜したほうがいい（忠告）","~하는 것이 좋다, ~해야 한다",["日本語が上手になりたければ、毎日少しずつでも話す<b>ことだ</b>。","風邪を早く治したいなら、ゆっくり休む<b>ことだ</b>。"],[349]],["〜ことだから","ことだから","〜だから（軽い理由）","~하니까, ~이기도 하니",["今日は天気もいい<b>ことだから</b>、散歩にでも行こうか。","せっかくここまで来た<b>ことだから</b>、もう少し先まで行ってみよう。"],[350]],["〜ことだけは","ことだけは","ほかは別として、〜ことは","~라는 것만은",["結果はどうであれ、努力したこと<b>だけは</b>認めてほしい。","何があっても、うそをつく<b>ことだけは</b>したくない。"],[351]],["〜ことだし","ことだし","〜から（軽い理由）","~하기도 하니, ~하니까",["せっかく京都まで来た<b>ことだし</b>、お寺をいくつか見て帰ろう。","天気もいい<b>ことだし</b>、窓を開けて掃除をしましょう。","雨も降ってきた<b>ことだし</b>、今日はもう帰りましょう。"],[173]],["〜ことで","ことで","〜することによって","~함으로써",["新しい機械を導入した<b>ことで</b>、作業時間が半分になった。","毎日日記を書く<b>ことで</b>、文章力が少しずつ伸びた。"],[243]],["〜ことといたします","ことといたします","〜ことにします（改まった言い方）","~하기로 하겠습니다",["今後、会議の資料はすべて電子データで配布する<b>ことといたします</b>。","本日の会議は、これで終了する<b>ことといたします</b>。"],[352]],["〜こととする","こととする","〜と決める（改まった言い方）","~하기로 한다",["締め切り後に届いた書類は受け付けない<b>こととします</b>。","応募者が多い場合は、抽選で決める<b>こととします</b>。"],[244]],["〜こととて","こととて","〜なので（おわび・事情の説明）","~인지라, ~이므로",["何分にも子どものした<b>こととて</b>、どうかお許しください。","慣れない土地の<b>こととて</b>、道に迷ってしまった。","休日の<b>こととて</b>、事務所には誰もいなかった。"],[142]],["〜ことなく／〜ことなしに","ことなく","〜しないで","~하는 일 없이, ~하지 않고",["彼女は一度も休む<b>ことなしに</b>、三年間練習に通い続けた。","この機械は休む<b>ことなく</b>、二十四時間動き続けている。","彼は一度も遅刻する<b>ことなく</b>、三年間学校に通った。"],[43]],["〜ことなど（なんて）できない","ことなどできない","〜ことはとてもできない","~하는 것 따위 할 수 없다",["こんなに難しい問題を一人で解く<b>ことなど</b>できない。","こんなにたくさんの料理を一人で食べる<b>ことなんて</b>できない。"],[353,354]],["〜ことにしてくれない？","ことにしてくれない","〜ということにしてほしい（頼む）","~한 걸로 해 주지 않을래?",["さっき言ったことは忘れて、なかった<b>ことにしてくれない</b>？","この話、聞かなかった<b>ことにしてくれない？</b>"],[355]],["〜ことによって","ことによって","〜という方法・原因で","~함으로써, ~함에 따라",["毎日練習を続ける<b>ことによって</b>、少しずつ上手になった。","インターネットが広まった<b>ことによって</b>、生活が大きく変わった。"],[356]],["〜ことはある","ことはある","時々〜する","~하는 일은 있다, ~할 때는 있다",["料理を作る<b>ことはある</b>ものの、人に出せるほど上手ではない。","たまに外食する<b>ことはある</b>が、たいていは家で食べる。"],[357]],["〜ことは否めない","ことはいなめない","〜ことは否定できない","~라는 것은 부정할 수 없다",["経験が足りないこと<b>は否めない</b>が、彼の熱意は本物だ。","準備不足だった<b>ことは否めない</b>。"],[218]],["〜こともあって","こともあって","〜という理由もあって","~하기도 해서, ~인 탓도 있어서",["連休という<b>こともあって</b>、道路はひどく混んでいた。","雨が降っていた<b>こともあって</b>、参加者は少なかった。"],[358]],["〜さえ","さえ","〜でも（ほかはもちろん）","~조차, ~마저",["専門家<b>さえ</b>解けない問題を、私が解けるはずがない。","彼の落ち着いた態度は、自信に満ちているように<b>さえ見える</b>。"],[245]],["〜さえ〜ば","さえば","〜だけあれば（それで十分だ）","~만 ~하면",["薬を飲んで一晩寝<b>さえすれば</b>、熱は下がるでしょう。","天気<b>さえ</b>よけれ<b>ば</b>、明日は富士山が見えるだろう。","時間<b>さえあれば</b>、もっと旅行に行きたい。"],[174]],["〜させてあげる","させてあげる","（相手がしたいことを）させる","~하게 해 주다",["子どもに好きな服を<b>選ばせてあげる</b>と、とても喜ぶ。","子どもがやりたいと言うことは、できるだけやら<b>せてあげたい</b>。"],[359]],["〜させてくれる","させてくれる","（相手が自分に）〜する気持ち・機会をくれる","(상대가 나에게) ~하게 해 주다",["先生の言葉は、もう一度挑戦してみようと<b>思わせてくれた</b>。","両親は、私に好きな道を選ば<b>せてくれた</b>。"],[360]],["〜させてしまう","させてしまう","（自然に・うっかり）〜させる","~하게 만들어 버리다",["彼女の笑顔は、周りの人をすぐに<b>安心させてしまう</b>。","彼の話には、聞く人を思わず<b>笑わせてしまう</b>不思議な魅力がある。"],[246]],["〜させてもらおうかと思って","させてもらおうかとおもって","〜しようと思う（ひかえめな言い方）","~할까 해서요 (허락을 구하는 공손한 표현)",["今日は体調が悪いので、早めに帰ら<b>せてもらおうかと思って</b>。","来週、一日休ま<b>せてもらおうかと思って</b>いるんです。"],[175]],["〜させられたあげく","させられたあげく","いやなのに〜させられて、その結果","(억지로) ~당한 끝에",["さんざん待たされた<b>あげく</b>、今日は診察できないと言われた。","二時間も話を聞か<b>されたあげく</b>、高い商品を買わされた。"],[361]],["〜させられる","させられる","（したくないのに）〜しろと言われてする／自然に〜と感じる","억지로 ~하다 / 저절로 ~하게 되다",["その映画を見て、家族の大切さについて<b>考えさせられた</b>。","子どものころ、嫌いな野菜を無理やり<b>食べさせられた</b>。"],[247]],["〜ざる","ざる","〜ない（古い言い方、名詞の前）","~하지 않는 (문어)",["科学の進歩は、研究者たちの<b>絶えざる</b>挑戦に支えられてきた。","平和は人々の<b>絶えざる</b>努力によって守られている。"],[248]],["〜ざるを得ない","ざるをえない","〜しないわけにはいかない","~하지 않을 수 없다",["上司の命令なので、気が進まなくてもやら<b>ざるを得ない</b>。","体調が悪かったので、旅行を中止<b>せざるを得なかった</b>。","台風が近づいているので、明日の試合は中止せ<b>ざるを得ない</b>。"],[97]],["〜しかあるまい","しかあるまい","〜するしかないだろう","~할 수밖에 없을 것이다",["誰も手伝ってくれないなら、自分でやる<b>しかあるまい</b>。","ここまで来たら、最後までやる<b>しかあるまい</b>。"],[363]],["〜しかない","しかない","〜するほかに方法がない","~할 수밖에 없다",["終電を逃してしまったので、タクシーで帰る<b>しかない</b>。","雨で試合が中止になった以上、来週まで待つ<b>しかない</b>。","道がわからないので、地図を見ながら歩く<b>しかない</b>。"],[176]],["〜し、〜し","しし","〜も…も（理由を並べる）","~하고 ~하고, ~하기도 하고",["財布はなくす<b>し</b>、電車には乗り遅れる<b>し</b>、今日は最悪だ。","この店は安い<b>し</b>、おいしい<b>し</b>、いつも混んでいる。"],[362]],["〜次第","しだい","〜したらすぐ","~하는 대로 (즉시)",["詳しいことが分かり<b>次第</b>、お知らせいたします。","準備ができ<b>次第</b>、出発します。"],[249]],["〜次第で（は）／〜次第だ","しだいで","〜によって（決まる）","~에 따라(서는), ~하기 나름이다",["天候<b>次第では</b>、明日の試合は中止になるかもしれない。","今後の練習<b>しだいでは</b>、レギュラーになれるかもしれない。","合格できるかどうかは、これからの努力<b>次第だ</b>。"],[112]],["〜次第です","しだいです","〜というわけです（事情の説明）","~하게 된 것입니다, ~한 바입니다",["先日のお礼を申し上げたく、お電話した<b>次第です</b>。","皆様のご協力をお願いしたく、ご連絡した<b>次第です</b>。"],[364]],["〜始末だ","しまつだ","（悪い経過の結果）ついに〜になる","(결국) ~하는 지경이다, ~하는 꼴이다",["彼は遅刻ばかりして、ついには無断で仕事を休む<b>始末だ</b>。","父は機械が苦手で、電話のかけ方まで孫に教わる<b>始末だ</b>。","彼は仕事を休みがちで、最近では電話にも出なくなる<b>始末だ</b>。"],[44]],["〜じゃない","じゃない","〜ではないか（気づき・確認）","~잖아",["なんだ、ちゃんとできてる<b>じゃない</b>。","ほら、言ったとおり<b>じゃない</b>。"],[365]],["〜末（に）","すえ","いろいろ〜したあとで（結果）","~한 끝에",["長い話し合い<b>の末</b>、ようやく結論が出た。","いろいろ考えた<b>末に</b>、会社を辞めることにした。"],[366]],["〜すぎる","すぎる","必要以上に〜","너무 ~하다",["このスープは辛<b>すぎて</b>、最後まで飲めなかった。","昨日は食べ<b>すぎて</b>、おなかが痛くなった。"],[367]],["〜ずくめ","ずくめ","〜ばかり（全部〜）","~일색, 온통 ~",["今年は昇進に結婚にと、いいこと<b>ずくめ</b>の一年だった。","この会社は細かい決まり<b>ずくめ</b>で、息が詰まりそうだ。","その男は、帽子から靴まで黒<b>ずくめ</b>の服装だった。"],[113]],["〜ずじまい","ずじまい","結局〜しないで終わる","결국 ~하지 못하고 말다",["楽しみにしていた映画は、忙しくて結局見<b>ずじまい</b>だった。","せっかく買った本を、忙しくて読ま<b>ずじまい</b>だった。","旅行中ずっと雨で、有名な山は一度も見られ<b>ずじまいだった</b>。"],[98]],["〜ずにすむ","ずにすむ","〜しなくてもよくなる","~하지 않아도 된다, ~하지 않고 끝나다",["友人が車で送ってくれたので、タクシーを使わ<b>ずにすんだ</b>。","もっと早く家を出ていれば、走ら<b>ずにすんだ</b>のに。"],[250]],["〜ずにはいられない／〜ないではいられない","ずにはいられない","がまんできず、どうしても〜してしまう","~하지 않고는 못 배기다, ~하지 않을 수 없다",["その映画のラストシーンには、泣か<b>ないではいられなかった</b>。","あまりにかわいい子犬だったので、思わず抱き上げ<b>ずにはいられなかった</b>。"],[251]],["〜ずにはおかない／〜ないではおかない","ずにはおかない","①必ず〜する　②自然に〜させる","①반드시 ~하고야 말겠다　②~하게 만들고야 만다",["彼の熱心な態度は、周りの人を動かさ<b>ないではおかない</b>。","彼女の歌声は、聴く人の心を揺さぶら<b>ずにはおかない</b>。","彼の熱のこもった演説は、聞く人の心を動かさ<b>ずにはおかない</b>。"],[56]],["〜ずにはすまない／〜ないではすまない","ずにはすまない","〜しないわけにはいかない（しないと許されない）","~하지 않고는 끝나지 않는다, ~해야만 한다",["約束を破ってしまったのだから、彼に謝ら<b>ずにはすまない</b>。","迷惑をかけた以上、先方に直接謝罪せ<b>ずにはすまない</b>。","人の物を壊したのだから、弁償し<b>ないではすまない</b>だろう。"],[68]],["〜すら／〜ですら","すら","〜さえ","~조차",["そのニュースを聞いて、声を出すこと<b>すら</b>できなかった。","彼女は怒っていて、私の話を聞いて<b>すら</b>くれなかった。","専門家<b>ですら</b>、この問題には答えられなかった。"],[24]],["せいぜい〜というところだ","せいぜいというところだ","多くても〜ぐらいだ","기껏해야 ~정도다",["この店の売り上げは、<b>せいぜい</b>一日5万円<b>というところだ</b>。","休みが取れても、<b>せいぜい</b>三日<b>というところだ</b>。"],[433]],["せめて〜だけでも","せめてだけでも","少なくとも〜だけは","적어도 ~만이라도",["忙しくても、<b>せめて</b>週末<b>だけでも</b>ゆっくり休みたい。","<b>せめて</b>一口<b>だけでも</b>食べてみてください。"],[252]],["〜そうになる","そうになる","もう少しで〜する","~할 뻔하다, ~할 것 같아지다",["電車のドアが閉まり<b>そうになった</b>ちょうどそのとき、彼が駆け込んできた。","道が凍っていて、何度も転び<b>そうになった</b>。"],[368]],["〜そうもない","そうもない","〜する可能性がほとんどない","~할 것 같지 않다",["仕事が今日中に終わり<b>そうもなく</b>、同僚に手伝いを頼んだ。","この雨では、今日中に作業が終わり<b>そうもない</b>。"],[253]],["〜そばから","そばから","〜しても、すぐまた","~하는 족족, ~하자마자 (곧 또)",["部屋を片づける<b>そばから</b>、子どもたちが散らかしていく。","習った<b>そばから</b>忘れてしまい、なかなか単語が覚えられない。","給料が入る<b>そばから</b>使ってしまうので、少しも貯金ができない。"],[35,371]],["〜そびれる","そびれる","〜する機会をなくす","~할 기회를 놓치다, 못 ~하고 말다",["昨夜は隣の部屋がうるさくて、寝<b>そびれて</b>しまった。","彼女に本当のことを言い<b>そびれた</b>まま、今日まで来てしまった。","朝寝坊して、朝ご飯を食べ<b>そびれた</b>。"],[88]],["〜たあげく","たあげく","いろいろ〜した結果（悪い結果）","~한 끝에 (결국)",["さんざん迷った<b>あげく</b>、結局何も買わずに店を出た。","何時間も並んだ<b>あげく</b>、チケットは売り切れだと言われた。"],[254]],["〜たいものだ","たいものだ","本当に〜したい","꼭 ~하고 싶다, ~하고 싶은 법이다",["一度でいいから、あんな大きな家に住んでみ<b>たいものだ</b>。","若いうちに、いろいろな国を旅行し<b>たいものだ</b>。"],[255]],["〜たうえで","たうえで","まず〜してから","~한 후에, ~한 다음에",["両親とよく話し合った<b>うえで</b>、留学することに決めた。","契約書の内容をよく確認した<b>うえで</b>、サインしてください。"],[256]],["〜たが最後／〜たら最後","たがさいご","一度〜したら、もう（だめだ）","일단 ~했다 하면 (끝이다)",["あの人は一度話し始め<b>たら最後</b>、何時間でも止まらない。","このお菓子は、一度食べ始めた<b>が最後</b>、やめられなくなる。","このゲームは一度始め<b>たら最後</b>、朝までやめられない。"],[36]],["VるだけVる","だけ","とにかく一度〜してみる／できるかぎり〜する","일단 ~해 보기는 하다 / ~할 만큼 ~하다",["断られるかもしれないが、頼む<b>だけ</b>頼んでみよう。","受かるかどうかわからないが、試験を受ける<b>だけ</b>受けてみるつもりだ。","使うかどうかわからないが、もらえるものはもらう<b>だけ</b>もらっておこう。"],[201]],["〜だけあって／〜だけのことはある","だけあって","さすが〜なので（それにふさわしく）","과연 ~인 만큼 / ~한 보람이 있다",["さすが元料理人<b>だけあって</b>、彼の作る料理はおいしい。","さすがプロ<b>だけあって</b>、料理の盛り付けが美しい。","十年も修業した<b>だけのことはあって</b>、彼の作るそばは本当においしい。"],[131]],["AだけでなくB（も）","だけでなく","Aに加えてBも","~뿐만 아니라 ~도",["この店は料理がおいしい<b>だけでなく</b>、店員の対応もとても丁寧だ。","彼女は英語<b>だけでなく</b>、フランス語<b>も</b>話せる。"],[387]],["〜だけに","だけに","〜なので、なおさら","~인 만큼 (더욱)",["期待していた<b>だけに</b>、不合格の知らせはショックだった。","彼は長年海外で暮らしていた<b>だけに</b>、外国の文化に詳しい。","長年の夢だった<b>だけに</b>、合格の知らせを聞いたときは涙が出た。"],[89]],["〜だけのN","だけの","〜するのに十分なN","~할 만한, ~할 만큼의",["家族が暮らしていける<b>だけの</b>収入は確保したい。","車を買う<b>だけの</b>お金は、まだたまっていない。"],[389]],["〜だけは","だけは","ほかは別として、〜は","~만은",["何があっても、約束<b>だけは</b>守るようにしている。","料理は苦手だが、カレー<b>だけは</b>自信がある。"],[259]],["〜だけましだ","だけましだ","よくはないが、〜だけまだいい","그나마 ~라서 다행이다",["財布は盗まれたが、パスポートが無事だった<b>だけまし</b>だ。","財布を落としたが、カードが入っていなかった<b>だけましだ</b>。","試合には負けたが、けが人が出なかった<b>だけましだ</b>。"],[114]],["〜ただけで","ただけで","〜しただけで（もう）","~한 것만으로",["説明書を<b>読んだだけで</b>使いこなせるとは限らない。","その話を聞い<b>ただけで</b>、涙が出てきた。"],[372]],["〜ただけでは","ただけでは","〜しただけでは（足りない）","~한 것만으로는",["写真を見た<b>だけでは</b>、その場所の本当の魅力はわからない。","一度会っ<b>ただけでは</b>、その人の性格はわからない。"],[373]],["ただ〜のみ","ただのみ","ただ〜だけ","오직 ~뿐",["合格できるかどうかは、<b>ただ</b>本人の努力<b>のみ</b>にかかっている。","試験の結果が出るまで、<b>ただ</b>待つ<b>のみ</b>だ。","今は<b>ただ</b>、皆の無事を祈る<b>のみ</b>だ。"],[200]],["ただ（ひとり）〜のみならず","ただのみならず","〜だけでなく（書き言葉）","비단 ~뿐만 아니라",["この問題は、<b>ただ</b>若者<b>のみならず</b>、社会全体で考えるべきことだ。","環境問題は、<b>ただ</b>一国<b>のみならず</b>、世界全体の課題である。"],[374,530]],["〜だって","だって","〜も・〜でも","~도, ~라도",["私<b>だって</b>、たまには一人でゆっくりしたいと思うことがある。","先生<b>だって</b>人間なのだから、間違えることもある。","そんなに難しい問題なら、先生<b>だって</b>すぐには解けないだろう。"],[177]],["〜たつもりが","たつもりが","〜したと思っていたが（実際は違った）","~한다는 것이 (그만), ~한 줄 알았는데",["冗談を言った<b>つもりが</b>、相手を怒らせてしまった。","塩を入れた<b>つもりが</b>、砂糖を入れてしまった。"],[375]],["〜たつもりでも","たつもりでも","〜したと思っていても","~했다고 생각해도",["説明した<b>つもりでも</b>、相手に伝わっていないことがある。","よく確認した<b>つもりでも</b>、間違いが残っていることがある。"],[376]],["たとえ〜ても","たとえても","もし〜でも","설령 ~하더라도",["たとえ失敗し<b>ても</b>、挑戦したことに意味がある。","<b>たとえ</b>親に反対され<b>ても</b>、私は留学するつもりだ。"],[377]],["〜たところ","たところ","〜したら（その結果）","~했더니, ~한 결과",["駅員に道を尋ねた<b>ところ</b>、親切に教えてくれた。","病院で検査を受けた<b>ところ</b>、異常は見つからなかった。"],[276]],["〜たところで","たところで","〜しても（むだだ）","~해 봤자",["今から勉強し<b>たところで</b>、明日の試験には間に合わない。","今さら謝った<b>ところで</b>、彼女は許してくれないだろう。","何度<b>説明したところで</b>、彼にはわかってもらえない。"],[1]],["〜たとする","たとする","〜たと仮定する","~했다고 치자, ~했다고 가정하다",["たとえば、あなたが道で財布を拾っ<b>たとします</b>。","仮に、宝くじで一億円当たっ<b>たとする</b>。あなたは何に使いますか。"],[379]],["〜たとたん（に）","たとたん","〜したちょうどその時に","~하자마자, ~한 순간",["社長が交代した<b>とたんに</b>、彼は手のひらを返したように態度を変えた。","家を出た<b>途端に</b>、雨が降り出した。"],[257]],["〜だに／〜だにしない","だに","〜するだけでも／まったく〜しない","~하는 것만으로도 / ~조차 하지 않다",["地震で家を失った人々のことは、想像する<b>だに</b>胸が痛む。","あの大地震がまた来るなんて、考える<b>だに</b>恐ろしい。","自分が代表に選ばれるとは、予想<b>だに</b>しなかった。"],[57]],["AだのBだの","だのだの","AとかBとか（不満など）","~라느니 ~라느니, ~이니 ~이니",["休みの日も、掃除<b>だの</b>洗濯<b>だの</b>で、ゆっくりする暇がない。","弟は、宿題が多い<b>だの</b>先生が厳しい<b>だの</b>、文句ばかり言っている。","彼女は、部屋が狭い<b>だの</b>駅から遠い<b>だの</b>と、新しい家の不満ばかり言っている。"],[178]],["〜たままだ","たままだ","〜した状態がそのまま続く","~한 채(이다)",["事故の原因は、今も謎に<b>包まれたままだ</b>。","彼は<b>黙ったまま</b>、窓の外を見ていた。"],[258]],["〜ため（に）","ため","〜の目的で／〜が原因で","~하기 위해 / ~때문에",["健康を保つ<b>ため</b>、毎朝三十分歩いている。","大雪の<b>ため</b>、電車が遅れている。"],[381,510]],["〜ためには","ためには","〜という目的のためには","~하기 위해서는",["健康を保つ<b>ためには</b>、十分な睡眠が欠かせない。","試験に合格する<b>ためには</b>、毎日の復習が欠かせない。"],[382]],["〜たら〜たで／〜ば〜で","たらたで","〜の場合はその場合で（別の問題がある・何とかなる）","~하면 ~하는 대로",["道に<b>迷ったら迷ったで</b>、それも旅のいい思い出になる。","お金がないと困るが、<b>あったらあったで</b>使い道に悩むものだ。","ペットを飼いたいと思っていたが、<b>飼ったら飼ったで</b>世話が大変だ。"],[130,563]],["〜たらなあ","たらなあ","〜だったらいいのに（願い）","~하면 좋을 텐데, ~했으면",["もっと時間があっ<b>たらなあ</b>。","私ももっと英語が話せ<b>たらなあ</b>。"],[384]],["〜たりとも（〜ない）","たりとも","たとえ（一〜）でも（〜ない）","단 ~라도 (~않다)",["この仕事では、1秒<b>たりとも</b>気を抜くことは許されない。","決勝戦では、一点<b>たりとも</b>相手に与えるわけにはいかない。","この一年間、彼女のことを一日<b>たりとも</b>忘れたことはない。"],[45]],["〜たり〜なかったり","たりなかったり","〜する時もしない時もある","~하기도 하고 안 하기도 하고",["彼は気分次第で、練習に来<b>たり来なかったり</b>だ。","朝ご飯は、食べ<b>たり</b>食べ<b>なかったり</b>だ。"],[385]],["〜たるもの","たるもの","〜という立場にある者は","~된 자는, ~라면 마땅히",["医師<b>たるもの</b>、患者の命を第一に考えなければならない。","教師<b>たる</b>もの、生徒の手本となるよう行動すべきだ。","経営者<b>たるもの</b>、社員の生活を守る責任がある。"],[46]],["〜だろうに","だろうに","〜はずなのに（残念・同情）","~했을 텐데, ~일 텐데",["もう少し早く家を出ていれば、電車に間に合った<b>だろうに</b>。","一言相談してくれれば力になれた<b>だろうに</b>。","一人で三人の子どもを育てるのは大変だった<b>だろうに</b>、母は一度も弱音を吐かなかった。"],[99]],["〜ちゃう","ちゃう","〜てしまう（話し言葉）","~해 버리다 (구어 축약)",["おいしくて、ケーキを全部食べ<b>ちゃった</b>。","早くしないと、電車が行っ<b>ちゃう</b>よ。"],[390]],["〜ちゃわないか","ちゃわないか","〜てしまわないか（さそい）","~해 버리지 않을래?",["時間がもったいないから、先に始め<b>ちゃわないか</b>。","雨が降りそうだから、今日のうちにやっ<b>ちゃわないか</b>。"],[391]],["つい〜てしまう","ついてしまう","そのつもりはないのに〜する","그만 ~해 버리다, 무심코 ~하다",["甘いものを見ると、<b>つい</b>手が出<b>てしまう</b>。","テレビがおもしろくて、<b>つい</b>夜遅くまで見<b>てしまった</b>。"],[396]],["〜ついでに","ついでに","〜する機会に、いっしょに","~하는 김에",["買い物に行った<b>ついでに</b>、郵便局で荷物を出してきた。","出張の<b>ついでに</b>、昔の友人に会ってきた。"],[397,512]],["〜っこない","っこない","絶対に〜ない（話し言葉）","~할 리가 없다",["こんな難しい問題、私に解け<b>っこない</b>。","いくら頼んでも、彼が貸してくれ<b>っこない</b>よ。"],[392]],["〜ったって","ったって","〜と言っても・〜しても（話し言葉）","~라고 해도, ~해 봤자",["急げ<b>ったって</b>、もう間に合わないよ。","今から行く<b>ったって</b>、もう店は閉まっているよ。"],[393]],["〜つ〜つ","つつ","〜たり〜たり（二つの動作をくり返す）","~하거니 ~하거니, ~했다 ~했다",["木の葉が川の流れに浮き<b>つ</b>沈み<b>つ</b>しながら流れていった。","彼は駅の前を行き<b>つ</b>戻り<b>つ</b>しながら、彼女を待っていた。","二台の車は、抜き<b>つ</b>抜かれ<b>つ</b>のレースを続けた。"],[90]],["〜つつある","つつある","だんだん〜している","(점점) ~해 가고 있다",["古い町並みは、開発によって少しずつ失われ<b>つつある</b>。","この町の人口は、年々減り<b>つつある</b>。","町の様子は少しずつ変わり<b>つつある</b>。"],[76]],["〜つつも","つつも","〜けれども（〜ながら）","~하면서도",["体に悪いと分かり<b>つつも</b>、ついタバコを吸ってしまう。","早く返事をしなければと思い<b>つつも</b>、まだ書いていない。"],[260]],["〜っぱなしだ","っぱなしだ","〜したまま（そのままにしている）","~한 채로 (내버려 두다), 계속 ~하고 있다",["今日は朝から会議が続き、座り<b>っぱなし</b>で腰が痛い。","使った道具を出し<b>っぱなし</b>にして、帰ってしまった。","窓を開け<b>っぱなし</b>にして出かけたら、部屋に雨が吹き込んでいた。"],[143]],["〜っぽい","っぽい","〜のように見える・よく〜する","~같다, ~스럽다, 잘 ~하다",["彼は三十歳だが、話し方が子ども<b>っぽい</b>。","最近、年のせいか忘れ<b>っぽく</b>なった。"],[395]],["〜つもりだ","つもりだ","〜しようと思っている","~할 생각이다, ~할 작정이다",["どんなに反対されても、留学をあきらめない<b>つもりだ</b>。","来年、国へ帰って仕事を探す<b>つもりだ</b>。"],[398]],["〜つもりで","つもりで","〜する気持ちで","~할 생각으로, ~하는 셈 치고",["励ます<b>つもりで</b>言った言葉が、かえって彼女を傷つけてしまった。","旅行に行った<b>つもりで</b>、そのお金を貯金した。"],[399]],["〜つもりでいる","つもりでいる","自分では〜と思っている","~한 줄로 알고 있다, ~할 생각으로 있다",["本人は上手に説明した<b>つもりでいる</b>が、聞き手には伝わっていない。","彼女はまだ若い<b>つもりでいる</b>ようだ。"],[400]],["〜つもりはなかったとしても","つもりはなかったとしても","〜する気持ちがなかったとしても","~할 생각은 없었다 해도",["傷つける<b>つもりはなかったとしても</b>、相手が傷ついたのなら謝るべきだ。","だます<b>つもりはなかったとしても</b>、結果的に彼をだましたことになる。"],[401]],["〜であれ／〜であろうと","であれ","たとえ〜でも","~이든, ~라 할지라도",["たとえ親<b>であれ</b>、子供の手紙を勝手に読んではいけない。","たとえ冗談<b>であれ</b>、人を傷つけるようなことを言ってはいけない。","どんなに優秀な人<b>であろうとも</b>、失敗することはある。"],[102]],["〜であれ〜であれ／〜であろうと〜であろうと","であれであれ","〜でも…でも（どちらでも同じ）","~이든 …이든",["仕事<b>であれ</b>遊び<b>であれ</b>、やるからには全力を尽くしたい。","大人<b>であれ</b>子ども<b>であれ</b>、ルールは守らなければならない。","プロ<b>であれ</b>アマチュア<b>であれ</b>、試合に臨む気持ちは同じだ。"],[103]],["〜でいい","でいい","〜で問題ない","~이면 된다, ~으로 괜찮다",["時間があるとき<b>でいい</b>から、この資料に目を通しておいて。","返事は急がないので、来週<b>でいい</b>ですよ。"],[267]],["〜でいいから","でいいから","〜でかまわないので（頼む）","~이라도 좋으니까",["少し<b>でいいから</b>、手伝ってくれない？","一度<b>でいいから</b>、オーロラを見てみたい。"],[423]],["〜ていたら〜はずだ","ていたらはずだ","もし〜していたら、きっと〜だった","~했더라면 ~했을 것이다",["もっと早く出発し<b>ていたら</b>、間に合った<b>はずだ</b>。","もっと勉強し<b>ていたら</b>、試験に合格できた<b>はずだ</b>。"],[402]],["〜ていては","ていては","〜している状態では（だめだ）","~하고 있어서는",["毎日ゲームばかりして<b>いては</b>、成績が下がるのも当然だ。","そんなに甘いものばかり食べ<b>ていては</b>、体を壊しますよ。"],[403]],["〜ていなければ","ていなければ","もし〜していなかったら","~하지 않았더라면",["あのとき先生に相談し<b>ていなければ</b>、今ごろ後悔していただろう。","期限までに書類を出して<b>いなければ</b>、申し込みは受け付けられない。"],[261]],["〜て以来","ていらい","〜してからずっと","~한 이래, ~한 후로 줄곧",["この町に引っ越し<b>て以来</b>、毎朝公園を散歩している。","日本に来<b>て以来</b>、毎日日本語で日記を書いている。"],[262]],["〜て（は）いられない","ていられない","〜している余裕がない・〜のままではいられない","~하고 있을 수 없다",["締め切りは明日の朝だ。テレビなんか見て<b>はいられない</b>。","雨がやむのを<b>待ってはいられない</b>。傘を借りて出かけよう。","友人が困っているのに、黙って<b>見てはいられない</b>。"],[100]],["〜ておけばいい","ておけばいい","とりあえず〜すれば十分だ","~해 두면 된다",["細かいことは気にせず、「はい」と<b>言っておけばいい</b>よ。","わからない言葉は、あとで調べ<b>ておけばいい</b>。"],[404]],["〜ておらず","ておらず","〜ていなくて（書き言葉）","~하고 있지 않고, ~되지 않아",["事故の原因はまだ明らかになって<b>おらず</b>、調査が続けられている。","新しい制度については、詳しいことがまだ決まって<b>おらず</b>、住民の間に不安が広がっている。"],[263]],["〜て（は）かなわない","てかなわない","〜で我慢できない・困る","~해서 견딜 수 없다, ~해서는 못 당하겠다",["毎日こんなに暑く<b>てはかなわない</b>。早く秋になってほしい。","毎晩隣の部屋がこううるさく<b>てはかなわない</b>。","毎晩こんなに騒がれ<b>てはかなわない</b>。"],[115]],["〜てからでないと","てからでないと","〜したあとでなければ（〜できない）","~하고 나서가 아니면",["実物を見<b>てからでないと</b>、買うかどうか決められない。","両親に相談し<b>てからでないと</b>、お返事できません。"],[405]],["〜てからでは遅い","てからではおそい","〜したあとでは間に合わない","~하고 나서는 늦는다",["病気になっ<b>てからでは遅い</b>ので、毎年健康診断を受けている。","事故が起き<b>てからでは遅い</b>。今のうちに対策を立てよう。"],[406]],["〜てからというもの","てからというもの","〜してからずっと（大きく変わった）","~하고 나서부터 줄곧",["子どもが生まれ<b>てからというもの</b>、毎日が忙しくなった。","犬を飼い始めて<b>からというもの</b>、毎朝早く起きるようになった。","留学して<b>からというもの</b>、彼女は積極的に意見を言うようになった。"],[69]],["〜てきた","てきた","（今まで）ずっと〜した・だんだん〜になった","~해 왔다, ~해졌다",["この祭りは、村の人々が三百年にわたって守り伝え<b>てきた</b>ものだ。","最近、だんだん暖かくなっ<b>てきた</b>。"],[407]],["〜てくれてもいいだろうに","てくれてもいいだろうに","〜してくれてもいいのに（不満）","~해 줘도 될 텐데",["遅れるなら、電話の一本ぐらいくれ<b>てもいいだろうに</b>。","忙しいのは知っているが、少しぐらい手伝っ<b>てくれてもいいだろうに</b>。"],[409]],["〜てくれればよかったのに","てくれればよかったのに","〜してくれなくて残念だ","~해 줬으면 좋았을 텐데",["来るなら連絡して<b>くれればよかったのに</b>。","困っていたなら、一言言っ<b>てくれればよかったのに</b>。"],[410]],["〜てこそ（はじめて）","てこそ","〜してはじめて（…できる）","~해야 비로소",["自分で働い<b>てこそはじめて</b>、お金のありがたさが分かる。","家族の支えがあっ<b>てこそ</b>、ここまで頑張ることができた。","実際に自分でやってみ<b>てこそ</b>、その難しさがわかるものだ。"],[153]],["〜て仕方ない","てしかたない","とても〜だ（抑えられない）","~해서 어쩔 수가 없다, 너무 ~하다",["あの時、正直に謝らなかったことが悔やまれ<b>て仕方ない</b>。","国の家族に会いたく<b>て仕方がない</b>。"],[411]],["〜でしかない","でしかない","ただ〜だけだ","~에 지나지 않는다, ~일 뿐이다",["それがうわさ<b>でしかない</b>ことに、彼は最後まで気付かなかった。","どんなに有名でも、彼は一人の人間<b>でしかない</b>。"],[268]],["〜てしかるべきだ","てしかるべきだ","〜するのが当然だ","~해야 마땅하다",["利用者の意見は、もっと計画に反映されて<b>しかるべきだ</b>。","長年会社に貢献してきた彼は、もっと評価され<b>てしかるべきだ</b>。","子どもの安全にかかわる問題なのだから、学校から保護者に説明があって<b>しかるべきだ</b>。"],[129]],["〜てしまう","てしまう","①全部〜する　②（残念なことに）〜する","~해 버리다, ~하고 말다",["好きな曲が流れると、体が自然に動い<b>てしまう</b>。","便利な道具に頼りすぎて、自分で考える習慣がなくなっ<b>てしまっている</b>。"],[412,413]],["〜てでも","てでも","どんな無理をしてでも","~해서라도",["何時間並ん<b>ででも</b>、あの店のラーメンを食べてみたい。","徹夜し<b>てでも</b>、明日までにこの報告書を仕上げます。","約束した以上、何とし<b>てでも</b>期限までに完成させる。"],[179,428]],["〜でなくてなんだろう","でなくてなんだろう","これこそ〜だ","~이 아니고 무엇이겠는가",["命をかけて子どもを守る、これが愛<b>でなくてなんだろう</b>。","何十年も同じ人を待ち続けるとは、これが愛<b>でなくて何だろう</b>。"],[132]],["〜でなくてはいけない","でなくてはいけない","〜でなければならない","~이어야 한다, ~이 아니면 안 된다",["人に物を頼むときは、言葉づかいが丁寧<b>でなくてはいけない</b>。","リーダーは、だれに対しても公平<b>でなくてはいけない</b>。"],[424]],["〜でなければ（〜ない）","でなければ","〜以外はだめだ","~이 아니면",["体が健康<b>でなければ</b>、どんな仕事も長くは続けられない。","この仕事は、経験のある人<b>でなければ</b>務まらない。"],[425,426]],["〜てならない","てならない","とても〜だ（気持ちを抑えられない）","~해서 견딜 수 없다, 너무 ~하다",["この計画はどこか無理があるように思われて<b>ならない</b>。","試験の結果が気になっ<b>てならない</b>。","故郷の母のことが心配<b>でならない</b>。"],[202]],["〜てなるものか","てなるものか","絶対に〜しない（強い気持ち）","~할까 보냐, ~하게 둘 수 없다",["こんなところで、あきらめ<b>てなるものか</b>。","あんな相手に負け<b>てなるものか</b>。"],[414]],["〜てのことだ","てのことだ","〜があったから・〜したうえでのことだ","~했기 때문이다, ~하고서 한 일이다",["彼が厳しいことを言うのも、君のためを思っ<b>てのことだ</b>。","彼が会社を辞めたのは、よく考え<b>てのことだ</b>。"],[264]],["〜ては","ては","①〜するたびに（くり返し）　②もし〜したら（困る）","①~하고는 (반복)　②~해서는, ~하면 (곤란하다)",["彼は昔の写真を取り出し<b>ては</b>、懐かしそうに眺めている。","祖母は、孫の写真を見<b>ては</b>、嬉しそうに笑っている。","そんなに食べ<b>ては</b>、おなかを壊しますよ。"],[154]],["〜では","では","〜という方法・場面では／〜によると","~(으)로는, ~에서는",["電話<b>では</b>説明しにくいので、直接会って話すことにした。","ニュース<b>では</b>、来月からガソリンの値段が上がるそうだ。"],[269]],["〜ではあるまいし／〜じゃあるまいし","ではあるまいし","〜ではないのだから","~도 아니고, ~도 아닌데",["一生会えない<b>わけではあるまいし</b>、そんなに泣かないで。","新人<b>じゃあるまいし</b>、こんな簡単なミスをしないでほしい。","小学生<b>ではあるまいし</b>、それくらい自分で考えなさい。"],[15]],["〜ては困る","てはこまる","〜されると困る","~하면 곤란하다",["大事な書類なので、なくされ<b>ては困る</b>。","大事な会議の日に<b>遅刻されては困る</b>。"],[265]],["〜てはじめて","てはじめて","〜したあとで、やっと","~하고 나서야 비로소",["一人暮らしをし<b>てはじめて</b>、親のありがたさがわかった。","病気になっ<b>てはじめて</b>、健康のありがたさに気づいた。"],[266]],["〜ては〜、〜ては〜","てはては","〜して…することを何度もくり返す","~하고는 …하고, ~하고는 …하고",["彼は何度も絵を描い<b>ては</b>破り、描い<b>ては</b>破りして、ようやく一枚を完成させた。","書い<b>ては</b>消し、書い<b>ては</b>消しして、やっと手紙を書き上げた。"],[416]],["〜ではないか","ではないか","なんと〜だ（驚き）／〜だろう（意見）","~이 아닌가",["箱を開けてみると、中は空っぽ<b>ではないか</b>。","ふと見ると、財布がなくなっている<b>ではないか</b>。"],[427]],["〜てはばからない","てはばからない","遠慮しないで堂々と〜する","거리낌 없이 ~하다, 서슴지 않고 ~하다",["彼女は、失敗はすべて部下のせいだと言っ<b>てはばからない</b>。","彼は、自分こそが世界一の料理人だと言っ<b>てはばからない</b>。","その監督は、次の作品が最高傑作になると明言し<b>てはばからない</b>。"],[155]],["〜てほしい","てほしい","相手に〜することを望む","~해 주었으면 한다, ~해 주길 바라다",["会議中にスマートフォンを触るのはやめ<b>てほしい</b>。","息子には、自分の好きな道を進ん<b>でほしい</b>。"],[417]],["〜手前","てまえ","〜した立場上・〜の前なので","~한 체면상, ~앞이라서",["部下に厳しく注意した<b>手前</b>、自分が遅刻するわけにはいかない。","自分から手伝うと申し出た<b>手前</b>、途中で帰るわけにはいかない。","手伝うと言ってしまった<b>手前</b>、今さら断れない。"],[144,442]],["〜てまで／〜までして","てまで","〜というひどいことをしてでも","~하면서까지, ~까지 해서",["人を傷つけ<b>てまで</b>、自分の利益を守りたいとは思わない。","睡眠時間を削っ<b>てまで</b>ゲームをするのは体に悪い。","借金をし<b>てまで</b>ブランド品を買う必要はない。"],[116,543]],["〜てみせる","てみせる","①必ず〜する（強い決意）　②実際にやって人に見せる","①(반드시) ~해 보이겠다　②(남 앞에서) ~해 보이다",["店員が、その機械の使い方を実際にやっ<b>てみせて</b>くれた。","三か月で、この店を町一番の人気店に<b>してみせます</b>。","今度の試験では、必ず満点を取っ<b>てみせる</b>。"],[101,547]],["〜てみてはどうだろうか","てみてはどうだろうか","〜してみたらどうか（提案）","~해 보면 어떨까",["迷っているなら、一度専門家に相談し<b>てみてはどうだろうか</b>。","一度、相手の立場に立って考え<b>てみてはどうだろうか</b>。"],[418]],["〜てみるもんだ","てみるもんだ","〜してみる価値があるものだ","~해 볼 만하다, ~해 보고 볼 일이다",["無理だと思っていたが、頼んで<b>みるもんだ</b>ね。","旅行なんて面倒だと思っていたが、行っ<b>てみるもんだ</b>なあ。"],[419]],["疑問詞＋〜ても","ても","どんなに〜しても","아무리·몇 번 ~해도",["<b>何度</b>説明し<b>ても</b>、彼は理解してくれなかった。","この本は<b>何回</b>読ん<b>でも</b>おもしろい。"],[420]],["〜てもさしつかえない","てもさしつかえない","〜しても問題ない","~해도 무방하다, ~해도 지장 없다",["この書類は、鉛筆で書い<b>てもさしつかえない</b>。","こちらの資料をお借りしても<b>差し支えないでしょうか</b>。","体調が悪い方は、途中で退席なさっ<b>てもさしつかえありません</b>。"],[117]],["〜でもしたら","でもしたら","もし〜のようなことをしたら（心配）","~하기라도 하면",["こんな大事な書類をなくし<b>でもしたら</b>、大変なことになる。","雨の日に自転車で転び<b>でもしたら</b>危ないよ。"],[270]],["〜ても始まらない","てもはじまらない","〜してもどうにもならない","~해 봤자 소용없다",["今さら後悔し<b>ても始まらない</b>。次のことを考えよう。","今さら文句を言っ<b>ても始まらない</b>から、できることから始めよう。"],[228]],["〜てもよさそうなものだ","てもよさそうなものだ","〜するのが普通なのに（不満）","~해도 좋으련만, ~할 법도 한데",["もう大人なんだから、自分の部屋くらい片付けて<b>もよさそうなものだ</b>。","一週間も前に送ったのだから、もう届い<b>てもよさそうなものだ</b>。"],[421]],["〜てもよろしいでしょうか","てもよろしいでしょうか","〜てもいいですか（ていねい）","~해도 괜찮겠습니까?",["こちらの資料を拝見し<b>てもよろしいでしょうか</b>。","明日、お電話を差し上げ<b>てもよろしいでしょうか</b>。"],[422]],["〜てやまない","てやまない","心からずっと〜している","~해 마지않다",["両国の友好関係が末永く続くことを願っ<b>てやまない</b>。","私たちは、彼の一日も早い回復を祈っ<b>てやまない</b>。","彼の作品は、今も多くの人を魅了し<b>てやまない</b>。"],[77]],["〜と（が）あいまって","とあいまって","〜と一緒になって（もっと効果が出る）","~와 어우러져, ~와 맞물려",["好天<b>とあいまって</b>、今年の祭りは大勢の人でにぎわった。","美しい景色が澄んだ空気<b>と相まって</b>、最高の休日になった。","才能と努力<b>とがあいまって</b>、彼は大成功を収めた。"],[70]],["〜とあって","とあって","〜という特別な事情なので","~(이)라서, ~라고 해서",["人気歌手が来る<b>とあって</b>、会場には朝から長い列ができた。","連休の最終日<b>とあって</b>、高速道路は車で渋滞している。","人気の歌手が出演する<b>とあって</b>、チケットはすぐに売り切れた。"],[2]],["〜とあっては","とあっては","〜という事情なら（〜しないわけにはいかない）","~라면야, ~라고 하니",["憧れの先輩に頼まれた<b>とあっては</b>、断るわけにはいかない。","子どものため<b>とあっては</b>、どんな苦労もいとわない。"],[203]],["〜とあれば","とあれば","〜という事情なら","~라면 (기꺼이·어쩔 수 없이)",["子どもの将来のため<b>とあれば</b>、どんな苦労もいとわない。","医者に止められた<b>とあれば</b>、試合を休むのもしかたがない。","社長の命令<b>とあれば</b>、休日でも出勤せざるを得ない。"],[37]],["〜といい…といい","といいといい","〜も…も（どれを見ても）","~도 그렇고 …도 그렇고",["兄<b>といい</b>弟<b>といい</b>、この家の子供たちはみんな背が高い。","母<b>といい</b>姉<b>といい</b>、うちの家族はみんな料理が上手だ。","この店は、料理<b>といい</b>サービス<b>といい</b>、申し分ない。"],[71]],["NというN","という","全部のN","~란 ~은 모두",["引き出し<b>という</b>引き出しを開けて、鍵を探した。","部屋の窓<b>という</b>窓を開けて、空気を入れ替えた。","窓<b>という</b>窓が、強風で割れてしまった。"],[180]],["〜というか〜というか","というかというか","〜とも…とも言える（うまく言えない）","~랄까 …랄까",["彼の服装は、個性的<b>というか</b>派手<b>というか</b>、とにかく目立つ。","彼の態度は、素直<b>というか</b>単純<b>というか</b>、見ていてほほえましい。","彼女の生き方は、自由<b>というか</b>大胆<b>というか</b>、とてもまねできない。"],[133]],["〜ということで","ということで","〜という理由で・〜という話で","~라고 해서, ~라는 이유로",["今日は社長が来る<b>ということで</b>、社員はみんな朝から緊張している。","全員賛成<b>ということで</b>、この案に決まりました。"],[429]],["〜ということのないように","ということのないように","〜ということが起こらないように","~하는 일이 없도록",["忘れ物をする<b>ということのないように</b>、前の晩に準備しておこう。","当日、遅刻する<b>ということのないように</b>、早めに家を出てください。"],[430]],["〜ということは","ということは","〜というのは、つまり","~라는 것은 (즉)",["日本で働く<b>ということは</b>、日本の習慣に合わせることでもある。","電気がついている<b>ということは</b>、まだだれかいるのだろう。"],[431]],["〜というだけで","というだけで","〜という理由だけで","~라는 이유만으로",["外国人だ<b>というだけで</b>、部屋を貸してもらえなかった。","駅から近い<b>っていうだけで</b>、家賃がずいぶん高くなる。"],[432,394]],["〜というのは","というのは","〜は（説明・定義）","~라는 것은, ~란",["親<b>というのは</b>、いくつになっても子どもを心配するものだ。","「デジカメ」<b>というのは</b>、デジタルカメラのことだ。"],[434]],["〜というものだ","というものだ","本当に〜だと思う","~라는 것이다, 그야말로 ~다",["困っている人がいたら助けるのが、人間<b>というものだ</b>。","人の話を最後まで聞かずに反論するのは、失礼<b>というものだ</b>。","約束の時間に一時間も遅れてくるなんて、無責任<b>というものだ</b>。"],[204]],["〜というものではない／〜ばいいというものではない","というものではない","いつも〜とは言えない","~라는 것은 아니다, ~하면 되는 것이 아니다",["高い薬を飲めば病気が早く治る<b>というものではない</b>。","練習時間が長ければうまくなる<b>というものではない</b>。","安けれ<b>ばいいというものではない</b>。品質も大切だ。"],[104]],["〜というような","というような","〜のような","~라는 식의, ~와 같은",["宝くじに当たる<b>というような</b>幸運は、めったに起こらない。","彼が犯人だ<b>というような</b>うわさが流れている。"],[435]],["〜というより","というより","〜と言うより、むしろ","~라기보다",["今日は暖かい<b>というより</b>、むしろ暑いくらいだ。","彼は先生<b>というより</b>、友達のような存在だ。"],[272]],["〜といえども","といえども","〜であっても","~라 할지라도, ~라고 해도",["社長<b>といえども</b>、会社の規則には従わなければならない。","小さな会社<b>といえども</b>、技術力では大企業に負けていない。","専門家<b>といえども</b>、すべての問題に答えられるわけではない。"],[25]],["〜と言えなくもない","といえなくもない","〜と言うこともできる","~라고 못 할 것도 없다",["見方を変えれば、これも一つの成功<b>と言えなくもない</b>。","少し高いが、質を考えれば安い<b>と言えなくもない</b>。"],[436]],["〜といえば","といえば","〜の話が出たら、すぐ思い出すのは","~라고 하면",["夏<b>といえば</b>、やっぱり花火大会ですね。","日本の花<b>といえば</b>、まず桜を思い浮かべる人が多い。"],[437]],["AといえばAが","といえばが","たしかにAだが（しかし）","~하다면 ~하지만",["この店の料理はおいしい<b>といえば</b>おいしい<b>が</b>、値段のわりには普通だ。","この仕事は大変<b>といえば</b>大変だ<b>が</b>、やりがいもある。"],[438]],["〜と言えば聞こえはいいが","といえばきこえはいいが","よく言えば〜だが、実際は","말이 좋아 ~이지",["自由業<b>と言えば聞こえはいいが</b>、実際は収入が不安定なだけだ。","節約家<b>と言えば聞こえはいいが</b>、彼はただのけちだ。"],[439]],["〜といえる","といえる","〜と言うことができる","~라고 할 수 있다",["この結果から、新しい方法は効果的だった<b>と言える</b>。","彼の作品は、現代美術の傑作<b>といえる</b>だろう。"],[273]],["〜といえるだろうか","といえるだろうか","〜とは言えない（反語）","~라고 할 수 있을까",["これで本当に問題が解決したと<b>いえるだろうか</b>。","相手の話を聞かないで、本当の話し合い<b>といえるだろうか</b>。"],[440]],["〜といった","といった","〜のような（例）","~와 같은",["京都や奈良<b>といった</b>古い町には、多くの観光客が訪れる。","この大学には、中国や韓国<b>といった</b>アジアの国からの留学生が多い。"],[441]],["〜といったところだ","といったところだ","だいたい〜ぐらいだ（多くても）","기껏해야 ~정도다",["毎日の勉強時間は、せいぜい1時間<b>といったところ</b>だ。","家から会社までは、電車で30分<b>といったところ</b>です。","この店の客は、平日だと一日20人<b>といったところだ</b>。"],[8]],["〜といったらない／〜といったらありはしない","といったらない","言葉にできないほど〜だ","~하기 이를 데 없다, 말도 못하게 ~하다",["一人で留守番をしていた夜の心細さ<b>といったらなかった</b>。","合格の知らせを聞いたときのうれしさ<b>といったらなかった</b>。","初めて富士山の頂上に立ったときの感動<b>といったらなかった</b>。"],[58]],["〜と言っていいほど","といっていいほど","〜と言ってもいいくらい（ほとんど）","~라고 해도 좋을 만큼",["彼は毎朝、必ず<b>と言っていいほど</b>同じ電車に乗っている。","この町の人は、全員<b>と言っていいほど</b>その祭りに参加する。"],[443]],["〜といっても","といっても","〜と言うが、実際は","~라고 해도",["料理ができる<b>といっても</b>、簡単なものしか作れません。","庭がある<b>といっても</b>、猫の額ほどの広さしかない。"],[205]],["〜と言ってもいい","といってもいい","〜と言うことができる","~라고 해도 좋다",["彼の作品は、日本文学の最高傑作<b>と言ってもいい</b>。","この十年は、私の人生で最も幸せな時期だった<b>と言ってもいい</b>。"],[444]],["〜と言っても過言ではない","といってもかごんではない","〜と言っても大げさではない","~라고 해도 과언이 아니다",["彼の発見が医学の歴史を変えた<b>といっても過言ではない</b>。","彼の努力がチームを優勝に導いた<b>と言っても過言ではない</b>。","彼はこの分野の第一人者だ<b>といっても過言ではない</b>。"],[105]],["〜といわず…といわず","といわずといわず","〜も…も区別なく全部","~며 …며 할 것 없이",["彼は、昼<b>といわず</b>夜<b>といわず</b>、研究に打ち込んでいる。","弟は顔<b>といわず</b>手<b>といわず</b>、泥だらけになって帰ってきた。","部屋の中は、床<b>といわず</b>机<b>といわず</b>、ほこりだらけだった。"],[78]],["〜同然","どうぜん","ほとんど〜と同じ","~나 다름없음",["このパソコンは一度しか使っていないので、新品<b>同然</b>だ。","二人は長い間いっしょに暮らしていて、家族<b>同然</b>だ。"],[462]],["とうてい〜ない","とうていない","どうしても〜できない","도저히 ~않다",["この量の仕事を一日で終わらせるのは、<b>とうてい</b>無理だ。","彼の言うことは、<b>とうてい</b>信じられ<b>ない</b>。"],[445]],["どうやら〜ようだ","どうやらようだ","はっきりしないが、たぶん〜らしい","아무래도 ~인 것 같다",["空が暗くなってきた。<b>どうやら</b>雨が降るようだ。","<b>どうやら</b>明日は雨になるようだ。"],[209]],["どうりで〜はずだ","どうりではずだ","（理由がわかって）〜のは当然だ","어쩐지 ~하더라니, 그러니 ~할 만도 하다",["毎日3時間も練習しているのか。<b>どうりで</b>上達が早い<b>はずだ</b>。","暖房がついていなかったのか。<b>どうりで</b>寒い<b>はずだ</b>。"],[463]],["〜と思いきや","とおもいきや","〜と思ったが、意外にも","~인 줄 알았는데 (뜻밖에)",["仕事が終わった<b>と思いきや</b>、また新しい仕事を頼まれた。","簡単に勝てる<b>と思いきや</b>、相手チームは意外に強かった。","今日は晴れる<b>かと思いきや</b>、午後から急に雨が降り出した。"],[10]],["〜と思われる","とおもわれる","〜と考えられる（自然にそう思う）","~라고 생각된다",["私には、この計画は少し無理があるように<b>思われる</b>。","犯人は窓から入ったもの<b>と思われる</b>。"],[446]],["〜とか","とか","〜と聞いた（はっきりしない）","~라던가, ~라고 하던데",["うわさでは、隣の課の田中さんが来月結婚する<b>とか</b>。","彼は忙しい<b>とか</b>言って、手伝ってくれない。"],[274]],["〜とかいう","とかいう","〜という名前らしい（はっきりしない）","~라던가 하는",["駅前に新しいデパートができる<b>とかいう</b>うわさを聞いた。","さっき、田中<b>とかいう</b>人から電話がありましたよ。"],[447]],["〜とかで","とかで","〜という理由だそうで","~라던가 해서, ~라나 해서",["田中さんは風邪を引いた<b>とかで</b>、今日は休みだそうだ。","電車が遅れた<b>とかで</b>、彼は30分も遅刻してきた。"],[448]],["〜ときたら","ときたら","〜は（不満・非難の気持ち）","~로 말할 것 같으면, ~은 정말이지",["父<b>ときたら</b>、休みの日は一日中テレビの前から動かない。","うちの犬<b>ときたら</b>、誰にでもしっぽを振ってついていく。","隣の犬<b>ときたら</b>、夜中でも大きな声で吠えるので眠れない。"],[38]],["〜時には","ときには","〜したその時にはもう","~했을 때에는 (이미)",["駅に着いた時<b>には</b>、もう最終電車は出てしまっていた。","気がついた<b>時には</b>、もう終電は出たあとだった。"],[449]],["〜とく","とく","〜ておく（話し言葉）","~해 두다 (구어 축약)",["ビールは冷蔵庫に冷やし<b>とく</b>ね。","必要な書類は机の上に置い<b>といた</b>よ。"],[275]],["〜どころか","どころか","〜とは反対に・〜はもちろん","~은커녕",["薬を飲んだが、熱は下がる<b>どころか</b>、ますます上がってしまった。","彼は謝る<b>どころか</b>、反対に私を責めてきた。"],[281]],["（危うく／もう少しで）〜ところだった","ところだった","もう少しで〜しそうだった","하마터면 ~할 뻔했다",["居眠りをしていて、<b>危うく</b>駅を乗り過ごす<b>ところだった</b>。","寝坊して、もう少しで電車に乗り遅れる<b>ところだった</b>。","<b>もう少しで</b>、彼の嘘を本当だと信じる<b>ところだった</b>。"],[450,233,551]],["〜どころではない","どころではない","〜する余裕はまったくない","~할 상황이 아니다, ~할 때가 아니다",["熱が出てしまい、パーティー<b>どころではなかった</b>。","試験前で、遊びに行く<b>どころではない</b>。"],[282]],["〜ところを","ところを","〜ときなのに（すまない気持ち・感謝）","~인데도, ~하신 중에",["お疲れの<b>ところを</b>、わざわざお越しいただき恐縮です。","お忙しい<b>ところを</b>お集まりいただき、ありがとうございます。","お休みの<b>ところを</b>お邪魔して、申し訳ありません。"],[26]],["〜と〜ざるとにかかわらず","とざるとにかかわらず","〜しても〜しなくても","~하든 ~하지 않든 (관계없이)",["<b>好むと好まざるとにかかわらず</b>、英語を使う機会はこれからも増えていくだろう。","<b>望むと望まざるとにかかわらず</b>、社会は変わっていく。"],[451]],["〜としか言いようがない","としかいいようがない","〜と言う以外に言い方がない","~라고밖에 말할 수 없다",["こんなに早く完成したのは、彼の努力の成果としか<b>言いようがない</b>。","あの事故で助かったのは、奇跡<b>としか言いようがない</b>。"],[452]],["〜としたところで","としたところで","〜としても（あまり変わらない）","~라고 해 봤자, ~한다 해도",["今からタクシーで行く<b>としたところで</b>、開始時間には間に合わない。","社長<b>としたところで</b>、この問題を一人で解決することはできないだろう。"],[206]],["〜として","として","〜の立場・資格で／〜と考えて","~로서 / ~라고 보고",["住民たちは、建設計画を違法<b>として</b>市を訴えた。","彼は通訳<b>として</b>国際会議に参加した。"],[277]],["〜としている","としている","（公的に）〜と言っている・考えている","~라고 밝히고 있다, ~라고 하고 있다",["気象庁は、今後も強い雨が続くおそれがある<b>としている</b>。","警察は、事故の原因を詳しく調べる<b>としている</b>。"],[453]],["〜とする","とする","〜ことにする・〜と決める／〜と仮定する","~하기로 하다 / ~라고 치다",["雨もやみそうにないし、今日は家で本でも読む<b>とするか</b>。","腹も減ったし、そろそろ昼飯を食べに行く<b>とするか</b>。","仮に、この話が本当だ<b>とする</b>。その場合、だれが得をするだろうか。"],[207]],["〜とすれば","とすれば","もし〜と仮定すれば","~라고 한다면",["この話が本当だ<b>とすれば</b>、大変なことになる。","今から出発する<b>とすれば</b>、到着は夜の10時ごろになる。"],[455]],["〜とて","とて","〜でも","~라 해도, ~도 역시",["専門家<b>とて</b>、すべての問題に答えられるわけではない。","強そうに見える彼<b>とて</b>、寂しいと感じることはあるだろう。","親<b>とて</b>、子どもの気持ちがすべてわかるわけではない。"],[134]],["〜とでもいうべき","とでもいうべき","〜と言ってもいいような","~라고나 할 만한",["この発見は、医学の革命<b>とでもいうべき</b>出来事だ。","彼はこのチームの心臓<b>とでもいうべき</b>選手だ。"],[278]],["〜となると","となると","〜の話・〜の場合になると","~(이)라면, ~하게 되면",["父は普段は無口だが、釣りの話<b>となると</b>止まらなくなる。","明日から大雪が降る<b>となると</b>、出張は延期したほうがよさそうだ。"],[279]],["〜との","との","〜という（内容の）","~라는",["会社から、来週の会議は中止する<b>との</b>知らせが届いた。","来週から料金が値上げされる<b>との</b>発表があった。","明日の会議は中止する<b>との</b>連絡があった。"],[156]],["〜とは","とは","①〜なんて（驚き）　②〜というのは（定義）","①~하다니　②~란, ~라는 것은",["こんな簡単な問題を間違える<b>とは</b>、自分でも信じられない。","あのまじめな彼が会社を辞める<b>とは</b>、思ってもみなかった。","「親友」<b>とは</b>、何でも話せる友達のことだ。"],[72]],["〜とはいうものの","とはいうものの","〜とは言っても（実際は）","~라고는 하지만",["春<b>とはいうものの</b>、まだ寒い日が続いている。","退院した<b>とはいうものの</b>、まだ無理はできない。"],[456]],["〜とはいえ","とはいえ","〜は事実だが、それでも","~라고는 해도",["一人暮らしに慣れた<b>とはいえ</b>、病気の時はやはり心細い。","上司の命令<b>とはいえ</b>、こんなやり方を続けていい<b>ものか</b>。","春になった<b>とはいえ</b>、朝晩はまだ寒い日が続いている。"],[27]],["〜とはかぎらない","とはかぎらない","いつも〜だとは言えない","~라고는 할 수 없다, 꼭 ~인 것은 아니다",["有名な大学を出た人が、仕事ができる<b>とは限らない</b>。","値段が高いからといって、品質がいい<b>とは限らない</b>。","高い料理が、必ずしもおいしい<b>とはかぎらない</b>。"],[208]],["〜とばかりに／〜と言わんばかりに","とばかりに","まるで〜と言うような様子で","마치 ~라는 듯이",["彼は待ってました<b>とばかりに</b>、手を挙げて発言し始めた。","父は「もう話すことはない」<b>とばかりに</b>、新聞を広げた。","母は、早く寝なさい<b>とばかりに</b>、部屋の電気を消した。"],[59]],["〜と引きかえに","とひきかえに","〜の代わりに（何かを失って得る）","~와 맞바꾸어, ~을 대가로",["彼は健康<b>と引きかえに</b>、莫大な財産を手に入れた。","彼は高い給料<b>と引きかえに</b>、自由な時間を失った。"],[457]],["〜とみえて","とみえて","〜らしく（様子から考えて）","~인 듯, ~인 모양으로",["彼はよほど疲れていた<b>とみえて</b>、ソファーで眠ってしまった。","彼女は何かいいことがあった<b>とみえて</b>、朝からずっと機嫌がいい。","弟はよほどお腹がすいていた<b>とみえて</b>、ご飯を三杯もおかわりした。"],[181]],["〜と見られる／〜と見られている","とみられる","〜と考えられている","~로 보인다, ~로 여겨지고 있다",["今年の夏は例年より暑くなる<b>と見られている</b>。","犯人は外部から侵入した<b>と見られている</b>。"],[280,458]],["〜ともあろう（者が）","ともあろう","〜という立派な立場の人が（意外・非難）","명색이 ~라는 사람이",["警察官<b>ともあろう</b>者が、法律を破るとは信じられない。","大学教授<b>ともあろうものが</b>、論文を盗用するなんて。","ベテランの医師<b>ともあろう</b>人が、こんな単純なミスをするとは。"],[106]],["〜ともいうべき","ともいうべき","〜と言ってもいいような","~라고도 할 만한",["富士山は、日本の心<b>ともいうべき</b>山だ。","この寺は、日本建築の最高傑作<b>ともいうべき</b>建物だ。"],[459]],["〜ともなく／〜ともなしに","ともなく","①特に〜するつもりもなく　②（どこ・だれ）かはっきりしないが","①무심코 ~, 딱히 ~하려던 것도 아닌데　②(어디)선지 모르게",["夕方になると、どこから<b>ともなく</b>鐘の音が聞こえてくる。","日曜日の午後、何を見る<b>ともなしに</b>テレビを眺めていた。","彼は誰に言う<b>ともなしに</b>、「疲れたなあ」とつぶやいた。"],[28]],["〜ともなると／〜ともなれば","ともなると","〜という段階・立場になると","~쯤 되면",["12月<b>ともなれば</b>、街はクリスマスの飾りで華やかになる。","店長<b>ともなれば</b>、売り上げの責任も一人で負うことになる。","社長<b>ともなれば</b>、会社全体のことを考えなければならない。"],[3]],["〜ないかぎり","ないかぎり","〜しなければ（ずっと）","~하지 않는 한",["本人が反省し<b>ない限り</b>、同じ失敗は繰り返されるだろう。","本人が努力し<b>ないかぎり</b>、成績は上がらないだろう。","雨が降らない<b>限り</b>、試合は予定どおり行われる。"],[157]],["〜ないことだ","ないことだ","〜しないほうがいい（忠告）","~하지 않는 것이 좋다",["風邪をひきたくなければ、夜更かしをしない<b>ことだ</b>。","やせたければ、夜遅くに食べ<b>ないことだ</b>。"],[465]],["〜ないことには","ないことには","〜しなければ（…できない）","~하지 않고서는",["実際に使ってみ<b>ないことには</b>、この機械のよさはわからない。","本人に聞いてみ<b>ないことには</b>、本当のことはわからない。"],[466]],["〜ないとも限らない","ないともかぎらない","〜するかもしれない","~하지 않는다고도 할 수 없다, ~할지도 모른다",["油断していると、思わぬ事故が起き<b>ないとも限らない</b>。","雨が降ら<b>ないとも限らない</b>から、傘を持って行こう。","地震が起き<b>ないとも限らない</b>から、水と食料を用意しておこう。"],[182,460]],["〜ないまでも","ないまでも","〜まではしなくても（せめて）","~까지는 아니더라도",["毎日とは言わ<b>ないまでも</b>、週に一度は連絡してほしい。","プロとは言わ<b>ないまでも</b>、彼の料理の腕はかなりのものだ。","完璧とは言え<b>ないまでも</b>、この計画はかなりよくできている。"],[16]],["〜ないものか","ないものか","なんとか〜できないだろうか（強い願い）","어떻게 ~할 수 없을까",["何とかこの渋滞を避けられ<b>ないものか</b>と、地図で別の道を探した。","もっと楽に英語が覚えられ<b>ないものか</b>。","この渋滞、何とかならない<b>ものか</b>。"],[183]],["〜ないものでもない／〜ないでもない／〜なくもない","ないものでもない","少しは〜する・〜する可能性もある","~하지 않는 것도 아니다",["条件によっては、その仕事を引き受け<b>ないものでもない</b>。","言われてみれば、彼の話にも一理ある気がし<b>なくもない</b>。","親が反対する理由も、考えてみれば理解でき<b>ないでもない</b>。"],[11]],["〜ないわけではない","ないわけではない","少しは〜する","~하지 않는 것은 아니다",["彼の気持ちもわから<b>ないわけではない</b>が、今回は賛成できない。","外国で働いてみたい気持ちが<b>ないわけではない</b>が、家族のことを考えると決心できない。"],[210]],["〜ながら","ながら","〜と同時に","~하면서",["父はいつも新聞を読み<b>ながら</b>朝ご飯を食べる。","彼女は音楽を聞き<b>ながら</b>、料理をしている。"],[283]],["〜ながらでも","ながらでも","〜している間でも","~하면서라도",["このアプリを使えば、家事をし<b>ながらでも</b>英語の勉強ができる。","働き<b>ながらでも</b>、大学で学ぶことはできる。"],[467]],["〜ながらに（して）／〜ながらの","ながらに","〜のままの状態で","~그대로(의), ~인 채로",["この町には、昔<b>ながらの</b>町並みが残っている。","衛星中継のおかげで、日本に<b>いながらにして</b>海外のサッカーの試合が見られる。"],[284]],["〜ながらも","ながらも","〜けれども","~이지만, ~하면서도",["狭い<b>ながらも</b>、日当たりのいい部屋で気に入っている。","彼は若い<b>ながらも</b>、しっかりした考えを持っている。","彼は文句を言い<b>ながらも</b>、最後まで仕事を手伝ってくれた。"],[91]],["〜なきにしもあらず","なきにしもあらず","まったくないわけではない","~이 없는 것도 아니다",["逆転の可能性も<b>なきにしもあらず</b>だから、最後まであきらめずに戦おう。","成功する可能性は、<b>なきにしもあらず</b>だ。"],[468]],["〜なきゃ","なきゃ","〜なければ（話し言葉）","~하지 않으면, ~해야지 (구어)",["おいしいかどうかは食べて<b>みなきゃ</b>わからない。","早く行か<b>なきゃ</b>、バスに乗り遅れるよ。"],[469]],["〜なくして（は）／〜なしに（は）","なくして","〜がなければ","~없이(는)",["家族の支え<b>なしには</b>、ここまで来ることはできなかった。","皆さんの協力<b>なしには</b>、このイベントは成功しなかった。","家族の協力<b>なくしては</b>、この仕事は続けられなかった。"],[0]],["〜なくてすむ","なくてすむ","〜しなくてもよくなる","~하지 않아도 된다",["友達が車で送ってくれたので、雨の中を歩か<b>なくてすんだ</b>。","駅の近くに引っ越したので、朝早く起き<b>なくてすむ</b>ようになった。"],[285]],["〜なさそうだ","なさそうだ","〜ないように見える","~하지 않을 것 같다, ~없어 보이다",["雨はしばらく止ま<b>なさそう</b>だから、タクシーで帰ろう。","この問題は、そんなに難しく<b>なさそうだ</b>。"],[470]],["なにも〜なくても","なにもなくても","そこまで〜する必要はないのに","굳이 ~하지 않아도",["<b>なにも</b>そこまで言わ<b>なくても</b>いいじゃないか。","<b>なにも</b>そんなに急が<b>なくても</b>、まだ時間はあるよ。"],[474]],["〜ならいざしらず","ならいざしらず","〜なら別だが（そうではないのだから）","~라면 몰라도",["子ども<b>ならいざしらず</b>、大人がこんなことで泣くなんて。","昔<b>ならいざしらず</b>、今は女性が働くのは当たり前だ。","平日<b>ならいざしらず</b>、週末のこの店は予約なしではまず入れない。"],[29]],["〜ならではの","ならではの","〜だけにある特別な","~만의, ~이기에 가능한",["地元の食材を使った、この町<b>ならではの</b>料理を味わった。","この料理には、地元の人<b>ならではの</b>工夫が詰まっている。","細かいところまで丁寧なこの仕上がりは、職人<b>ならではだ</b>。"],[7]],["AならまだしもB","ならまだしも","Aならまだいいが、Bは（だめだ）","~라면 또 몰라도",["一度<b>ならまだしも</b>、何度も同じミスをされては困る。","子ども<b>ならまだしも</b>、大人がそんなことをするとは信じられない。"],[476]],["〜なり","なり","〜するとすぐに","~하자마자",["娘は家に帰る<b>なり</b>、自分の部屋に閉じこもってしまった。","彼は部屋に入る<b>なり</b>、窓を全部開け放った。","父は手紙を読む<b>なり</b>、顔色を変えた。"],[39]],["〜なり…なり","なりなり","〜でも…でも（どちらかを選ぶ）","~든지 …든지",["困ったときは、先生<b>なり</b>先輩<b>なり</b>に相談してみるといい。","疲れたら、コーヒー<b>なり何なり</b>飲んで休んでください。","時間があるなら、本を読む<b>なり</b>映画を見る<b>なり</b>したらどう？"],[21]],["〜なりに／〜なりの","なりに","〜にふさわしい程度で","~나름대로 / ~나름의",["狭い部屋だが、狭いなら狭い<b>なりに</b>工夫して使っている。","子どもは子ども<b>なりに</b>、親のことを心配しているものだ。","新人の彼も彼<b>なりに</b>、早く仕事を覚えようと頑張っている。"],[30]],["〜なんか","なんか","〜など（軽く見る・例）","~따위, ~같은 것",["疲れているときは、料理<b>なんか</b>したくない。","お金<b>なんか</b>なくても、幸せに暮らせる。"],[477]],["〜なんて","なんて","〜など・〜とは（軽く見る・驚き）","~따위, ~라니",["小学生がこんな難しい問題を解ける<b>なんて</b>、驚いた。","傘<b>なんて</b>雨がしのげればどれでもいいと思っていたが、軽い傘を使ってみたら手放せなくなった。","山田<b>なんて</b>人は、この会社にはいませんよ。"],[211]],["なんという〜だろう","なんというだろう","本当に〜だ（感動・驚き）","이 얼마나 ~인가",["<b>なんという</b>美しい景色だろう。","自分の子どもを捨てるとは、<b>なんという</b>親<b>だろう</b>。"],[478]],["なんと〜ことか","なんとことか","とても〜だ（感動）","얼마나 ~한지 (모른다), 정말 ~하구나",["合格の知らせを聞いて、<b>なんと</b>うれしかった<b>ことか</b>。","家族そろって食事ができるのは、<b>なんと</b>幸せな<b>ことか</b>。"],[479]],["何の〜にもなっていない","なんのにもなっていない","少しも〜になっていない","아무런 ~도 되지 않는다",["そんな言い訳は<b>何の</b>解決<b>にもなっていない</b>。","彼の説明は、<b>何の</b>答え<b>にもなっていない</b>。"],[473]],["なんら〜ない","なんらない","少しも〜ない","아무런 ~도 없다, 전혀 ~않다",["私はこの事件とは<b>なんら</b>関係がない。","手続きには<b>なんら</b>問題は<b>ない</b>。"],[480]],["AにB","に","AにBを加えて（組み合わせ）","~에 ~ (곁들임·조합)",["ご飯<b>に</b>みそ汁という和風の朝食が好きだ。","白いシャツ<b>に</b>黒いズボンという服装で来てください。"],[481]],["VるにVれない","に","〜したくてもできない","~하려야 ~할 수 없다",["みんなが熱心に話しているので、<b>帰るに帰れなかった</b>。","旅行の当日に寝坊して飛行機に乗り遅れ、<b>泣くに泣けない</b>思いをした。","本当のことを<b>言うに言えない</b>まま、時間だけが過ぎていった。"],[161]],["〜にあたって","にあたって","〜する（大切な）ときに","~함에 있어서, ~할 때에",["新しい生活を始める<b>にあたって</b>、家具を一通りそろえた。","開会<b>にあたって</b>、一言ごあいさつ申し上げます。"],[482]],["〜にあって（は／も）","にあって","〜という（特別な）状況で","~에 있어서(는), ~라는 상황에서(도)",["戦時下<b>にあって</b>、人々は互いに助け合って暮らしていた。","どんな逆境<b>にあっても</b>、彼は決して希望を捨てなかった。","いかなる状況に<b>あっても</b>、冷静さを失ってはならない。"],[47]],["〜に至って（も）","にいたって","〜という（重大な）段階になって","~에 이르러서(도)",["死者が出る<b>にいたって</b>、ようやく安全対策が見直された。","被害が広がる<b>に至っても</b>、会社は責任を認めようとしない。","大きな事故が起きる<b>に至って初めて</b>、市は信号の設置を決めた。"],[79]],["〜にいたっては","にいたっては","〜の場合は（特にひどい例）","~에 이르러서는, ~로 말하자면 (더 심해서)",["事態がここ<b>にいたっては</b>、計画を中止するしかないだろう。","家族全員が朝に弱いが、弟<b>に至っては</b>昼まで起きてこない。","このクラスは遅刻する学生が多いが、田中君<b>にいたっては</b>一週間毎日遅刻している。"],[158]],["〜にいたる","にいたる","（長い経過のあと）〜になる","~에 이르다",["二人は何年も話し合いを重ね、ついに和解する<b>に至った</b>。","長い話し合いの末、両社は合併する<b>にいたった</b>。"],[286]],["〜（から）〜に至るまで","にいたるまで","〜から…まで全部","~에서 …에 이르기까지",["この店では、日用品から高級家具<b>に至るまで</b>、何でもそろう。","その事件は、子ども<b>から</b>老人<b>にいたるまで</b>、誰もが知っている。","その作家は、原稿の内容から表紙のデザイン<b>に至るまで</b>、細かく注文をつける。"],[107]],["〜に言わせると／〜に言わせれば","にいわせると","〜の意見では","~의 말로는, ~에게 말하라고 하면",["祖母<b>に言わせると</b>、最近の若者は我慢が足りないそうだ。","祖父<b>に言わせれば</b>、今の夏は昔よりずっと暑いそうだ。","専門家<b>に言わせれば</b>、この程度の地震は珍しくないそうだ。"],[92]],["〜においてさえ","においてさえ","〜でも","~에서조차",["医学が進歩した今日<b>においてさえ</b>、治せない病気は多い。","専門家の間<b>においてさえ</b>、意見が分かれている。"],[287]],["〜に応じて","におうじて","〜に合わせて","~에 따라, ~에 맞게",["参加者の人数<b>に応じて</b>、会場の広さを決めます。","収入<b>に応じて</b>、税金の額が変わる。"],[288]],["〜に負うところが大きい","におうところがおおきい","〜のおかげが大きい","~에 힘입은 바가 크다",["今回の成功は、スタッフの努力に<b>負うところが大きい</b>。","この研究の成果は、若い研究者たちの努力<b>に負うところが大きい</b>。"],[483]],["〜に思いをいたす","におもいをいたす","〜のことを深く考える","~을 깊이 생각하다, ~에 생각이 미치다",["被災地の人々の苦労<b>に思いをいたし</b>、支援を続けたい。","平和な毎日の中で、戦争で亡くなった人々<b>に思いをいたす</b>。"],[484]],["〜に及んで","におよんで","〜という段階になって（やっと）","~에 이르러(서야), ~할 지경이 되어",["赤字が三年も続く<b>に及んで</b>、社長はついに辞任を決意した。","問題が国会で取り上げられる<b>に及んで</b>、会社はやっと謝罪した。","被害が全国に広がる<b>に及んで</b>、政府はようやく対策に乗り出した。"],[184]],["〜にかかっている","にかかっている","〜で決まる","~에 달려 있다",["試合に勝てるかどうかは、選手たちの体調<b>にかかっている</b>。","チームが優勝できるかどうかは、君の活躍<b>にかかっている</b>。","新商品が売れるかどうかは、宣伝のやり方いかん<b>にかかっている</b>。"],[93]],["〜にかかわらず","にかかわらず","〜に関係なく","~에 관계없이",["参加の有無<b>にかかわらず</b>、メールで返事をしてください。","年齢や経験<b>にかかわらず</b>、だれでも応募できます。"],[485]],["〜にかかわる","にかかわる","〜に（重大な）関係がある","~에 관계되다, ~이 걸린",["少しの不注意が、命に<b>かかわる</b>事故につながることもある。","人の命<b>にかかわる</b>仕事である<b>以上</b>、小さなミスも許されない。","睡眠不足は、仕事の質に<b>かかわる</b>重要な問題だ。"],[145]],["〜にかぎったことではない","にかぎったことではない","〜だけの話ではない","~에만 국한된 일이 아니다",["ストレスを抱えているのは、大人<b>にかぎったことではない</b>。","スマートフォンに頼りすぎるのは、若者<b>に限ったことではない</b>。","若者の活字離れは、日本<b>にかぎったことではない</b>。"],[118]],["〜に限らず","にかぎらず","〜だけでなく","~뿐만 아니라, ~에 한하지 않고",["この店は、若者<b>に限らず</b>お年寄りにも人気がある。","日本<b>に限らず</b>、多くの国で少子化が問題になっている。"],[289]],["〜に限る","にかぎる","〜がいちばんいい","~이 최고다, ~이 제일이다",["旅行の情報を集めるなら、現地の人に聞く<b>に限る</b>。","疲れたときは、温かいお風呂に入る<b>に限る</b>。"],[290]],["〜にかけては","にかけては","〜の分野では（だれにも負けない）","~에 있어서는, ~에 관한 한",["料理の腕<b>にかけては</b>、彼の右に出る者はいない。","走ること<b>にかけては</b>、クラスのだれにも負けない。"],[486]],["〜にかこつけて","にかこつけて","〜を口実にして","~을 핑계 삼아",["彼は友人の結婚式<b>にかこつけて</b>、一週間も休みを取った。","彼は出張<b>にかこつけて</b>、観光を楽しんでいた。","息子は勉強<b>にかこつけて</b>、毎晩遅くまで友達の家にいる。"],[159]],["〜にかたくない","にかたくない","簡単に〜できる（想像・理解）","~하기 어렵지 않다",["一人で異国に来た留学生の心細さは、想像<b>にかたくない</b>。","長年勤めた会社を去る彼の寂しさは、察する<b>にかたくない</b>。","突然家族を失った彼の悲しみは、想像<b>にかたくない</b>。"],[80]],["〜にかまけて","にかまけて","〜に気を取られて、ほかのことをしないで","~에 정신이 팔려, ~에 얽매여",["忙しさ<b>にかまけて</b>、家族と過ごす時間を作れずにいる。","仕事<b>にかまけて</b>、子どもの話を聞いてやれなかった。"],[487]],["〜に代わって","にかわって","〜の代わりに","~을 대신해서",["入院中の父<b>に代わって</b>、わたしが式に出席した。","社長<b>に代わって</b>、副社長が会議に出席した。"],[488]],["〜に関しては","にかんしては","〜については","~에 관해서는",["この件<b>に関しては</b>、後日改めてご説明いたします。","環境問題<b>に関しては</b>、国際的な協力が欠かせない。"],[291]],["〜に決まっている","にきまっている","絶対〜だと思う","~일 게 뻔하다, 틀림없이 ~이다",["こんなに練習したのだから、合格する<b>に決まっている</b>。","そんなに夜ふかしをしたら、明日寝坊する<b>にきまっている</b>。"],[212]],["〜に加え（て）","にくわえ","〜だけでなく、さらに","~에 더하여, ~뿐만 아니라",["彼は英語<b>に加え</b>、中国語も話せる。","大雨<b>に加えて</b>、風も強くなってきた。"],[489]],["〜に越したことはない","にこしたことはない","〜のほうがいい（当然）","~보다 좋은 것은 없다, ~하는 게 제일이다",["経験はある<b>に越したことはない</b>が、なくても応募できる。","健康のためには、早寝早起きをする<b>に越したことはない</b>。","体調が悪いときは、早めに病院へ行く<b>にこしたことはない</b>。"],[60]],["〜に応えて","にこたえて","（期待・要望）に合うように","~에 부응하여",["店はお客様の声<b>に応えて</b>、営業時間を延長した。","観客のアンコール<b>に応えて</b>、歌手はもう一曲歌った。"],[490]],["〜に際して","にさいして","〜するときに（改まった言い方）","~에 즈음하여, ~할 때에",["契約を結ぶ<b>に際して</b>、内容をもう一度確認した。","卒業<b>に際して</b>、先生から心に残る言葉をいただいた。"],[491]],["〜に先立ち","にさきだち","〜の前に（準備として）","~에 앞서",["開会<b>に先立ち</b>、主催者があいさつをした。","試合<b>に先立ち</b>、両チームの選手が紹介された。"],[492]],["〜にしたら／〜にしてみれば／〜にすれば","にしたら","〜の立場から見ると","~입장에서 보면",["親<b>にすれば</b>、子どもの帰りが遅いと心配になるのは当然だ。","小さな失敗でも、本人<b>にしてみれば</b>大きなショックだったのだろう。","親<b>にしてみれば</b>、子供はいつまでも子供だ。"],[119]],["〜にして","にして","①〜になってはじめて・〜でさえ　②〜であり、同時に","①~이 되어서야, ~조차도　②~이면서 동시에",["この味は、経験豊かな料理人<b>にして初めて</b>出せるものだ。","彼は四十歳<b>にして</b>、ようやく自分の進む道を見つけた。","天才と呼ばれた彼<b>にして</b>、この問題は解けなかったそうだ。"],[31]],["〜にしては","にしては","〜から考えると意外に","~치고는",["初めて作った<b>にしては</b>、このケーキはなかなかおいしい。","このレストランは、駅前<b>にしては</b>静かで落ち着いている。","新人<b>にしては</b>、彼の営業成績はなかなかのものだ。"],[185]],["〜にしても／〜にしろ／〜にせよ","にしても","たとえ〜でも・〜の場合も","~라 하더라도, ~이든",["大企業<b>にしても</b>、この不況では人員削減を避けられない。","プロ<b>には及ばないにしても</b>、彼の料理の腕はなかなかのものだ。","どんな理由がある<b>にしろ</b>、暴力は許されない。"],[146,464]],["〜にしろ〜にしろ／〜にせよ〜にせよ","にしろにしろ","〜でも…でも（どちらの場合も）","~이든 …이든",["行く<b>にしろ</b>行かない<b>にしろ</b>、早めに返事をしてください。","賛成<b>にしろ</b>反対<b>にしろ</b>、自分の意見をはっきり言うべきだ。"],[292]],["〜にすぎない","にすぎない","ただ〜だけだ","~에 지나지 않는다",["これはあくまでも私の個人的な意見<b>にすぎない</b>。","それは単なるうわさ<b>にすぎない</b>。"],[493]],["〜に即して／〜に即した","にそくして","〜に合わせて","~에 입각해서, ~에 맞게",["事実<b>に即して</b>、事故の状況を詳しく報告してください。","新しい制度は、地域の実情<b>に即して</b>運用されるべきだ。","現場の実態<b>に即した</b>対策を考える必要がある。"],[81]],["〜に対し（て）","にたいし","〜に向かって・〜とは反対に","~에 대해 / ~와는 달리",["住民の要望<b>に対し</b>、市は早急に対応すると答えた。","目上の人<b>に対して</b>、そんな言い方をしてはいけない。"],[494]],["〜に対する","にたいする","〜への","~에 대한",["若者の政治<b>に対する</b>関心が低くなっている。","環境<b>に対する</b>意識が年々高まっている。"],[293]],["〜にたえない","にたえない","①ひどくて〜していられない　②とても〜だ（感謝・後悔など）","①차마 ~할 수 없다　②~해 마지않다, ~을 금할 수 없다",["酔った客同士のけんかは、見る<b>にたえない</b>ものだった。","最近のネット上の書き込みには、読む<b>にたえない</b>ものが多い。","被災地の様子をテレビで見て、同情の念<b>にたえない</b>。"],[48]],["〜にたえる","にたえる","〜するだけの価値がある／〜にがまんできる","~할 만하다 / ~을 견디다",["この作品は、大人の鑑賞<b>にたえる</b>本格的なアニメーションだ。","素人の作品だが、十分鑑賞<b>にたえる</b>出来だ。","長年の使用<b>にたえる</b>丈夫な家具を選びたい。"],[120]],["〜に足る／〜に足りない","にたる","〜する価値がある／ない","~하기에 충분하다, ~할 만하다 / ~할 가치가 없다",["そんな噂は取る<b>にたりない</b>ものだから、気にしなくていい。","彼の説明には、私たちを納得させる<b>に足る</b>根拠がなかった。","彼は信頼する<b>に足る</b>人物だから、安心して仕事を任せられる。"],[135]],["〜に違いない","にちがいない","きっと〜だ","~임에 틀림없다",["彼があんなにうれしそうなのは、何かいいことがあった<b>に違いない</b>。","部屋の電気が消えている。彼はもう寝た<b>に違いない</b>。"],[495]],["〜について","について","〜のことを（話す・考える）","~에 대해서",["将来の進路<b>について</b>、両親とよく話し合った。","日本の歴史<b>について</b>、レポートを書いた。"],[496]],["〜につき","につき","〜のため（お知らせ）／〜ごとに","~이므로 / ~당",["本日は定休日<b>につき</b>、お休みさせていただきます。","工事中<b>につき</b>、この道は通れません。"],[497]],["〜につけ","につけ","〜するたびに（いつも）","~할 때마다",["母は何か<b>につけ</b>、子どもの頃の私の失敗を話題にする。","故郷の写真を見る<b>につけ</b>、子どもの頃を思い出す。"],[294]],["〜につけ〜につけ","につけにつけ","〜の時も…の時も","~하든 …하든, ~할 때나 …할 때나",["うれしい<b>につけ</b>悲しい<b>につけ</b>、思い出すのは故郷のことだ。","雨<b>につけ</b>風<b>につけ</b>、ふるさとの両親のことが気にかかる。"],[498]],["〜につれて","につれて","〜が変わると、いっしょに","~함에 따라",["年をとる<b>につれて</b>、昔のことをよく思い出すようになった。","試験の日が近づく<b>につれて</b>、不安が大きくなってきた。"],[295]],["〜にて","にて","〜で（場所・方法、改まった言い方）","~에서, ~(으)로",["ご質問は、受付窓口<b>にて</b>承ります。","説明会は、3階の会議室<b>にて</b>行います。"],[499]],["〜に転じる","にてんじる","〜に変わる","~로 돌아서다, ~로 전환되다",["売り上げは、三年ぶりに増加<b>に転じた</b>。","減り続けていた人口が、増加<b>に転じた</b>。"],[500]],["〜にと","にと","〜のためにと思って","~에게 주려고, ~용으로",["母の誕生日のプレゼント<b>にと</b>、花束を買った。","これは、子どものおやつ<b>にと</b>思って買ってきたものです。"],[501]],["〜にとって","にとって","〜の立場から見ると","~에게 있어서, ~에게는",["この公園は、近所の子どもたち<b>にとって</b>大切な遊び場だ。","留学生<b>にとって</b>、一番大変なのは住む場所を探すことだ。","この問題は、私たちの世代<b>にとっても</b>重要な課題だ。"],[160]],["二度と〜ない","にどとない","もう決して〜しない","두 번 다시 ~하지 않다",["あんな怖い思いをしたのだから、二度とあの山には登り<b>はしない</b>。","こんな失敗は、<b>二度と</b>くり返し<b>はしない</b>。"],[502]],["〜（だけ／のみ）にとどまらず","にとどまらず","〜だけでなく（さらに広く）","~에 그치지 않고",["彼の活躍は国内<b>にとどまらず</b>、海外にまで広がっている。","この運動は学生<b>にとどまらず</b>、一般の市民にも広がった。","環境問題は一つの国<b>にとどまらず</b>、地球全体の問題だ。"],[49,388,519]],["〜に伴って／〜に伴う","にともなって","〜と一緒に（変化する）","~에 따라, ~와 함께 / ~에 따른",["気温が上がる<b>にともなって</b>、電力の使用量も増えていく。","人口の増加<b>にともなって</b>、住宅不足が深刻になった。","人口の減少<b>に伴う</b>労働力不足が深刻になっている。"],[187]],["AにBにと","ににと","AにもBにも（いろいろ）","~에 ~에, ~이며 ~이며",["彼女は仕事<b>に</b>子育て<b>にと</b>、毎日忙しく過ごしている。","週末は掃除に洗濯に<b>と</b>、休む暇がない。","春になる<b>と</b>、この川の両岸には桜が咲く。"],[296,271]],["〜に則って","にのっとって","（規則・基準）に従って","~에 따라, ~에 의거하여",["式は昔からのしきたり<b>に則って</b>、厳かに行われた。","試合は国際ルール<b>に則って</b>行われる。"],[188]],["〜にのぼる","にのぼる","（数量が）〜にもなる","~에 달하다, ~에 이르다",["今回の地震による被害額は、100億円<b>にのぼる</b>という。","この事故で、けが人は200人<b>にのぼった</b>。","この病気に悩む人は、国内で百万人<b>にのぼる</b>と言われている。"],[121]],["〜には","には","〜するためには","~하려면, ~하기에는",["この本を一日で読む<b>には</b>、かなりの集中力が必要だ。","外国の文化を理解する<b>には</b>、その国の歴史を知ることが必要だ。"],[162]],["〜にはあたらない","にはあたらない","〜するほどのことではない","~할 것까지는 없다, ~할 만한 일은 아니다",["一度の失敗くらいで、そんなに落ち込む<b>にはあたらない</b>。","目上の人に疑問点を質問すること自体は、決して失礼<b>にはあたらない</b>。","彼の実力なら、優勝したとしても驚く<b>にはあたらない</b>。"],[147]],["〜には及ばない","にはおよばない","①〜する必要はない　②〜にはかなわない","①~할 필요는 없다　②~에는 미치지 못한다",["この店のケーキは有名店のもの<b>には及ばない</b>が、値段が手ごろだ。","その程度のけがなら、心配する<b>には及ばない</b>。","私の料理の腕は、まだまだ母<b>には及ばない</b>。"],[163]],["〜に恥じない","にはじない","〜の名前にふさわしい","~에 부끄럽지 않은",["優勝チームの名<b>に恥じない</b>試合をしたい。","彼は、チャンピオンの名<b>に恥じない</b>すばらしい試合をした。"],[504]],["〜にひきかえ","にひきかえ","〜とは反対に","~와는 반대로, ~에 비해",["兄が社交的なの<b>にひきかえ</b>、弟は人前で話すのが苦手だ。","明るい姉<b>にひきかえ</b>、妹はおとなしくて人見知りだ。","去年の夏が涼しかったの<b>にひきかえ</b>、今年は猛暑が続いている。"],[73]],["〜にほかならない","にほかならない","まさに〜だ（それ以外ではない）","바로 ~이다, ~에 다름 아니다",["彼が成功したのは、毎日の努力の結果<b>にほかならない</b>。","言葉は、その国の文化そのもの<b>にほかならない</b>。"],[297]],["〜に向けて","にむけて","〜を目標にして","~을 향해, ~을 목표로",["新店舗のオープン<b>に向けて</b>、スタッフ全員で準備を進めている。","来月のオリンピック<b>に向けて</b>、選手たちは毎日厳しい練習を重ねている。"],[298]],["〜にもかかわらず","にもかかわらず","〜のに","~에도 불구하고",["大雨<b>にもかかわらず</b>、試合は予定どおり行われた。","何度も注意された<b>にもかかわらず</b>、彼はまた同じミスをした。"],[505]],["〜にもほどがある","にもほどがある","〜すぎる（ひどい）","~에도 정도가 있다",["何度も同じ失敗をするなんて、不注意<b>にもほどがある</b>。","約束の時間に三時間も遅れるなんて、いいかげん<b>にもほどがある</b>。"],[299]],["〜にもまして","にもまして","〜以上に","~보다 더, ~이상으로",["今年の新入社員は、去年<b>にもまして</b>やる気に満ちている。","今年の夏は去年<b>にもまして</b>暑い日が続いている。","病気をしてから、彼は以前<b>にもまして</b>健康に気を使うようになった。"],[51]],["〜に由来する","にゆらいする","〜から来ている","~에서 유래하다",["この町の名前は、昔ここにあった大きな寺に<b>由来する</b>。","この祭りは、古い農村の行事<b>に由来する</b>。"],[213]],["〜によって","によって","〜で（違う）・〜が原因／方法で","~에 따라, ~에 의해",["その出会い<b>によって</b>、彼は人生に対する考え方を大きく変えた。","人<b>によって</b>、同じ映画でも感じ方が違う。"],[300]],["〜によっては","によっては","〜の場合には（〜こともある）","~에 따라서는",["天候<b>によっては</b>、試合が中止になる場合もある。","場合<b>によっては</b>、予定を変更することもあります。"],[506]],["〜によらず","によらず","〜に関係なく","~와 상관없이, ~에 의하지 않고",["この仕事は、年齢や経験<b>によらず</b>、誰でも応募できる。","当店の商品は、サイズ<b>によらず</b>すべて同じ値段です。"],[301]],["〜によるところが大きい","によるところがおおきい","〜のおかげ・〜が主な原因だ","~에 힘입은 바가 크다, ~덕이 크다",["今回の優勝は、監督の的確な指導<b>によるところが大きい</b>。","この地域の発展は、新しい鉄道の開通<b>によるところが大きい</b>。","彼の成功は、家族の支え<b>によるところが大きい</b>。"],[189]],["〜ぬく","ぬく","最後まで〜する","끝까지 ~하다, ~해 내다",["彼女は最後まであきらめずに、四十二キロを走り<b>ぬいた</b>。","厳しい練習に<b>耐えぬいた末に</b>、ついに代表に選ばれた。"],[302]],["〜ねばならない","ねばならない","〜しなければならない","~하지 않으면 안 된다, ~해야 한다",["市民の安全を守るために、早急に対策を講じ<b>ねばならない</b>。","約束は守ら<b>ねばならない</b>。","約束した以上、最後までやり遂げ<b>ねばならない</b>。"],[148]],["〜のあまり","のあまり","〜すぎて（その結果）","~한 나머지",["彼は合格の知らせを聞いて、喜び<b>のあまり</b>泣き出した。","彼女は悲しみ<b>のあまり</b>、何も食べられなくなった。"],[507]],["〜の至り","のいたり","この上なく〜だ（改まった言い方）","~하기 그지없음, ~의 극치",["先生にお越しいただけるとは、光栄<b>の至り</b>でございます。","私の拙い発表に長時間お付き合いいただき、恐縮<b>の至り</b>です。","このような立派な賞をいただき、感激<b>の至り</b>です。"],[190]],["〜のがやっとだ","のがやっとだ","〜するだけで精一杯だ","~하는 것이 고작이다, 겨우 ~하다",["熱が高くて、起き上がる<b>のさえやっと</b>だった。","給料が安くて、家族を養う<b>のがやっとだ</b>。"],[508]],["〜の極み","のきわみ","これ以上ないほど〜だ","~의 극치, 더없는 ~",["多くの方に支えられてこの日を迎えられ、感激<b>の極み</b>です。","人生の最後を家族に囲まれて過ごせるのは、幸せ<b>の極み</b>だ。","一流ホテルのスイートルームに泊まるなんて、贅沢<b>の極み</b>だ。"],[136]],["〜のことだ（から）","のことだ","〜の性格・いつもの様子から考えると","~이니까 (분명), ~의 일이니",["几帳面な彼女<b>のことだ</b>から、約束の時間には必ず来るだろう。","まじめな彼<b>のことだから</b>、約束は必ず守るだろう。"],[509]],["〜のだから","のだから","〜という事実があるから（当然）","~이니까, ~한 것이니",["自分で決めた<b>のだから</b>、最後まで責任を持ちなさい。","もう子どもではない<b>のだから</b>、自分のことは自分で決めなさい。"],[511]],["〜のではあるまいか","のではあるまいか","〜のではないだろうか（書き言葉）","~이 아닐까",["このままでは、地球の環境はますます悪化する<b>のではあるまいか</b>。","この計画には、どこか無理がある<b>のではあるまいか</b>。"],[513]],["〜のではという","のではという","〜のではないかという","~이 아닐까 하는",["失敗する<b>のではという</b>不安が消えない。","また地震が起こる<b>のではという</b>心配から、眠れない人も多い。"],[514]],["〜のではないか","のではないか","〜かもしれないと思う","~이 아닐까, ~일지도 모른다",["彼は約束を忘れている<b>のではないか</b>と心配になった。","このままでは間に合わない<b>のではないか</b>と心配だ。"],[515]],["〜のなんの","のなんの","とても〜だ（話し言葉）","어찌나 ~한지, 엄청 ~하다",["昨日の試験は難しい<b>のなんの</b>、半分も解けなかった。","初めてのバンジージャンプは怖い<b>のなんの</b>、足が震えて止まらなかった。","久しぶりに会った祖母が喜んだ<b>のなんの</b>、涙を流して抱きしめてくれた。"],[215]],["〜のに対して","のにたいして","〜とは反対に（比べる）","~인 데 반해",["兄が社交的な<b>のに対して</b>、弟はおとなしい性格だ。","姉が静かな<b>のに対して</b>、妹はとてもおしゃべりだ。"],[516]],["〜のはいいのだが","のはいいのだが","〜のはいいが（別の問題がある）","~한 것은 좋은데",["駅に近い<b>のはいいのだが</b>、電車の音がうるさくて眠れない。","新しい家に引っ越した<b>のはいいのだが</b>、駅から遠くて不便だ。"],[517]],["〜のみならず","のみならず","〜だけでなく","~뿐만 아니라",["この映画は子ども<b>のみならず</b>、大人の心も強く動かす。","この歌は日本<b>のみならず</b>、海外でも広く知られている。","彼は語学力<b>のみならず</b>、交渉力においても優れている。"],[216,518]],["〜のもとで","のもとで","〜の下で（指導・影響を受けて）","~밑에서, ~아래에서",["彼は有名な職人<b>のもとで</b>、十年間家具作りを学んだ。","子どもは、両親の愛情<b>のもとで</b>育つのが一番だ。"],[520]],["〜のもとに（で）","のもとに","〜という条件・状況で","~하에, ~아래",["先生の指導<b>のもとに</b>、実験を行った。","全員の合意<b>のもとに</b>、計画が進められた。"],[521]],["〜のやら","のやら","〜のかわからない","~하는 건지 (모르겠다)",["息子は毎晩遅く帰ってくるが、どこで何をしている<b>のやら</b>。","何から手をつけていい<b>のやら</b>、見当もつかない。","この調子では、工事はいつ終わる<b>のやら</b>。"],[217]],["〜のをいいことに","のをいいことに","〜という状況をうまく利用して（悪いことをする）","~을 기회 삼아, ~을 빌미로",["親が留守な<b>のをいいことに</b>、弟は一日中ゲームをしていた。","先生がいない<b>のをいいことに</b>、生徒たちは騒ぎ始めた。"],[303]],["〜ばいい","ばいい","〜すればそれで十分だ","~하면 된다",["形は悪くても、おいしく食べられれ<b>ばいい</b>。","わからないことがあったら、先生に聞け<b>ばいい</b>。"],[525]],["〜ばいいだけのことだ","ばいいだけのことだ","〜すれば済む（簡単なことだ）","~하면 그만이다",["失敗したら、もう一度やり直せ<b>ばいいだけのこと</b>だ。","気に入らなければ、断れ<b>ばいいだけのことだ</b>。"],[526]],["〜は言うに及ばず／〜は言うまでもなく","はいうにおよばず","〜はもちろん","~은 말할 것도 없고",["彼は国内<b>は言うに及ばず</b>、海外でも名の知られた画家だ。","この歌手は、国内は<b>言うにおよばず</b>、海外でも人気がある。","彼女は英語<b>は言うまでもなく</b>、フランス語やドイツ語も話せる。"],[137]],["〜はおろか","はおろか","〜はもちろん（…さえも）","~은커녕, ~은 고사하고",["忙しくて、旅行<b>はおろか</b>、近所を散歩する時間さえない。","足をけがして、走ること<b>はおろか</b>歩くこともできない。","祖父は機械に弱く、パソコン<b>はおろか</b>携帯電話<b>すら</b>使えない。"],[32]],["〜ばかりか","ばかりか","〜だけでなく（そのうえ）","~뿐만 아니라",["その歌手は、日本<b>ばかりか</b>アジアの国々でも人気がある。","彼は約束の時間に遅れた<b>ばかりか</b>、謝りもしなかった。","彼は遅刻した<b>ばかりか</b>、宿題まで忘れてきた。"],[223]],["〜ばかりだ","ばかりだ","どんどん〜していく（悪い方向）","~하기만 한다, ~해 갈 뿐이다",["駅前に大型店ができてから、商店街の客は減る<b>ばかりだ</b>。","連絡のないまま時間が過ぎ、心配は増す<b>ばかり</b>だった。"],[305]],["〜ばかりに","ばかりに","ただ〜のせいで（悪い結果）","~한 탓에, ~하는 바람에",["道を一本まちがえた<b>ばかりに</b>、約束の時間に遅れてしまった。","パスワードを忘れた<b>ばかりに</b>、大事なメールを読めなかった。","一度うそをついた<b>ばかりに</b>、だれにも信じてもらえなくなった。"],[224,380]],["〜ばかりになっている","ばかりになっている","もう〜するだけの状態だ（準備ができた）","~하기만 하면 되는 상태다",["荷造りも済み、あとは出発する<b>ばかりになっている</b>。","新しい店の内装も完成し、あとは開店の日を迎える<b>ばかりになっている</b>。","料理の準備もでき、あとは客の到着を待つ<b>ばかりとなった</b>。"],[164]],["〜ばきりがない／〜たらきりがない","ばきりがない","〜し始めると終わりがない","~하자면 끝이 없다",["彼の欠点を挙げれば<b>きりがない</b>が、根は優しい人だ。","細かいことを気にし始め<b>たらきりがない</b>。"],[527,383]],["〜ばこそ","ばこそ","〜からこそ","(바로) ~이기에, ~하기 때문에",["君のことを心配していれ<b>ばこそ</b>、厳しいことを言うのだ。","子どものことを思え<b>ばこそ</b>、親は厳しく注意するのだ。","家族の支えがあれ<b>ばこそ</b>、つらい治療にも耐えられたのです。"],[33]],["〜はさておき","はさておき","〜は今は考えないで","~은 제쳐 두고",["値段<b>はさておき</b>、このレストランの料理は見た目が美しい。","結果<b>はさておき</b>、最後まであきらめずに頑張ったことが大切だ。","誰が言い出したか<b>はさておき</b>、まずは計画を実行に移そう。"],[122]],["〜はしない","はしない","（決して）〜しない（強い否定）","~하지는 않는다",["少し失敗したくらいで、彼はあきらめ<b>はしない</b>だろう。","一度裏切られた相手を、二度と信じ<b>はしない</b>。","一度失った信頼は、簡単には戻り<b>はしない</b>。"],[219]],["〜ばそれでいい","ばそれでいい","〜ならそれで十分だ","~하면 그걸로 됐다",["みんなが楽しめれ<b>ばそれでいいじゃないか</b>。","子どもが元気でいてくれれ<b>ばそれでいい</b>。"],[528]],["〜ばそれまでだ","ばそれまでだ","〜したら、すべて終わりだ","~하면 그걸로 끝이다",["いくらいい計画を立てても、実行しなけれ<b>ばそれまでだ</b>。","どんなに練習しても、本番で実力を出せなけれ<b>ばそれまでだ</b>。","苦労して書いた原稿も、データが消えてしまえ<b>ばそれまでだ</b>。"],[123]],["果たして〜だろうか","はたしてだろうか","本当に〜だろうか（疑い）","과연 ~일까",["<b>果たして</b>彼の予想は当たるのだろうか。","この方法で、<b>果たして</b>うまくいく<b>だろうか</b>。"],[522]],["AはAで","はで","AはAとして（別の事情がある）","~은 ~대로",["都会の生活も大変だが、<b>田舎は田舎で</b>不便なことが多い。","学生は気楽だと言われるが、学生<b>は</b>学生<b>で</b>悩みがある。"],[304]],["〜はというと","はというと","一方、〜は（比べて言う）","~은 어떤가 하면, ~로 말하자면",["姉は社交的で友達が多い。妹<b>はというと</b>、家で本を読むのが好きなタイプだ。","家族はみんな旅行に出かけたが、私<b>はというと</b>、家で留守番だ。"],[523]],["〜はともかく","はともかく","〜は今は問題にしないで","~은 어찌 되었든, ~은 둘째 치고",["結果<b>はともかく</b>、最後まであきらめなかったことが大切だ。","味<b>はともかく</b>、この店は量が多くて学生に人気がある。"],[220]],["〜ば、〜のに","ばのに","もし〜なら…なのに（実際は違う）","~하면 …할 텐데",["もっと早く起きれ<b>ば</b>、間に合った<b>のに</b>。","お金があれ<b>ば</b>、世界中を旅行できる<b>のに</b>。"],[524]],["〜はめになる","はめになる","（望まないのに）〜することになる","~하는 처지가 되다, ~하는 신세가 되다",["傘を忘れたせいで、雨の中を駅まで走る<b>はめになった</b>。","財布を落としたので、駅から家まで歩いて帰る<b>はめになった</b>。"],[221]],["〜はもとより","はもとより","〜はもちろん","~은 물론",["この映画は子ども<b>はもとより</b>、大人も楽しめる。","この店は和食<b>はもとより</b>、洋食<b>まで</b>何でもある。"],[222]],["〜ぶる","ぶる","〜のようにふるまう（本当は違う）","~인 체하다, ~인 척하다",["大した仕事もしていないのに、彼はいつも偉<b>ぶって</b>いる。","彼は知らないくせに、いつも学者<b>ぶって</b>難しい言葉を使う。","彼女は人前では上品<b>ぶって</b>いるが、家ではとても気さくだ。"],[191]],["〜分（だけ）","ぶん","〜した程度に合わせて、それだけ","~한 만큼",["今月は残業が増えた<b>分</b>、給料も多かった。","練習した<b>分だけ</b>、上手になる。"],[531]],["〜分には","ぶんには","〜するだけなら（問題ない）","~하는 한에서는, ~하기에는",["見ている<b>分には</b>簡単そうだが、実際にやってみると難しい。","一人で楽しむ<b>分には</b>、何を歌ってもかまわない。"],[532]],["〜べからず／〜べからざる","べからず","〜してはいけない／〜てはならない（N）","~하지 말 것 / ~해서는 안 될",["「展示品に手を触れる<b>べからず</b>」という注意書きがある。","彼は社会人として許す<b>べからざる</b>過ちを犯した。","「初心忘る<b>べからず</b>」という言葉を胸に、毎日練習に励んでいる。"],[52]],["〜べきか否か","べきかいなか","〜するべきかどうか","~해야 할지 말지",["会社を辞める<b>べきか否か</b>、ずっと悩んでいる。","手術を受ける<b>べきか否か</b>、家族で話し合った。"],[533]],["〜べきだ","べきだ","〜するのが当然だ・正しい","~해야 한다",["自分の間違いに気づいたら、すぐに謝る<b>べきだ</b>。","約束は守る<b>べきだ</b>。"],[534]],["〜べきだった","べきだった","〜すればよかった（後悔）","~했어야 했다",["こんなに雨が降るなら、傘を持ってくる<b>べきだった</b>。","もっと早く病院に行く<b>べきだった</b>。"],[535]],["〜べきではない","べきではない","〜するのはよくない","~해서는 안 된다",["他人の悪口は言う<b>べきではない</b>。","人を見た目で判断する<b>べきではない</b>。"],[536]],["〜べきではないだろうか","べきではないだろうか","〜するべきだと思う","~해야 하지 않을까",["子どもの教育費は、もっと国が負担<b>すべきではないだろうか</b>。","私たちは、もっと自然を大切にする<b>べきではないだろうか</b>。"],[537]],["〜べく","べく","〜するために","~하기 위해, ~하고자",["政府は景気を回復させる<b>べく</b>、新たな政策を打ち出した。","新しい市場を開拓<b>すべく</b>、社長自ら海外へ向かった。","大学に合格<b>すべく</b>、毎日夜遅くまで勉強している。"],[4]],["〜べくして","べくして","当然〜するはずで（〜した）","~할 만해서 (~했다), 필연적으로",["準備を重ねてきた彼らは、勝つ<b>べくして</b>勝ったのだ。","準備不足だったのだから、この失敗は起こる<b>べくして</b>起こったと言える。","毎日誰よりも練習していた彼女は、優勝する<b>べくして</b>優勝したと言える。"],[165]],["〜べくもない","べくもない","とても〜できない","~할 수 있을 리 없다, ~할 길이 없다",["小さな町の病院では、最新の設備など<b>望むべくもない</b>。","初心者の私の演奏は、先生の演奏には及ぶ<b>べくもない</b>。","当時の詳しい事情は、今となっては知る<b>べくもない</b>。"],[61]],["〜ほか","ほか","〜に加えて、ほかにも","~외에",["大雨で道路が通行止めになった<b>ほか</b>、一部の地域では停電も起きた。","会議には、社長の<b>ほか</b>、各部の部長も出席した。"],[538]],["〜ほど","ほど","〜くらい（程度）／〜すれば、それだけ","~만큼, ~정도 / ~할수록",["年をとる<b>ほど</b>、時間が早く過ぎるように感じる。","昨日の試験は、泣きたくなる<b>ほど</b>難しかった。"],[306]],["〜ほどだ","ほどだ","〜くらいだ（程度の例）","~할 정도다",["彼の演奏はすばらしく、感動して泣き出す人<b>もいるほどだ</b>。","昨日は疲れて、食事もできない<b>ほどだった</b>。"],[539]],["〜ほど…ない","ほどない","〜と言えるほど…ではない","~할 만큼 …않다",["一晩勉強しただけで合格できる<b>ほど</b>、試験は簡単ではない。","一度話した<b>だけで</b>分かり合える<b>ほど</b>、人間は単純ではない。"],[307]],["〜ほどのことではない","ほどのことではない","〜する必要があるほど大きなことではない","~할 정도의 일은 아니다",["この程度のけがなら、病院へ行く<b>ほどのことではない</b>。","ちょっとした失敗なので、そんなに気にする<b>ほどのことではない</b>。"],[308]],["〜ほど〜はない","ほどはない","〜がいちばん…だ","~만큼 …한 것은 없다",["母の作る料理<b>ほど</b>おいしいものは<b>ない</b>。","家族と過ごす時間<b>ほど</b>大切なもの<b>はない</b>。"],[540]],["〜まい","まい","①もう〜しない（決意）　②〜ないだろう","①~하지 않겠다　②~하지 않을 것이다",["こんなつらい思いは、もう二度とする<b>まい</b>と心に決めた。","あの頑固な父のことだから、私の意見など聞く<b>まい</b>。","あんなひどい店には、二度と行く<b>まい</b>と思った。"],[166]],["〜まいとして","まいとして","〜しないようにしようと思って","~하지 않으려고",["母を心配させ<b>まいとして</b>、彼は病気のことを黙っていた。","彼女は涙を見せ<b>まいとして</b>、ずっと笑顔でいた。"],[309]],["〜（として）あるまじき","まじき","〜として、してはならない","~로서 있어서는 안 될",["客の秘密を漏らすなど、弁護士として許す<b>まじき</b>行為だ。","審判に暴言を吐くなど、スポーツ選手に<b>あるまじき</b>態度だ。","患者の個人情報を外部に漏らすなど、医者に<b>あるまじき</b>行為だ。"],[82,454]],["まして（や）〜","まして","〜の場合は、もっとそうだ","하물며 ~은 더 말할 것도 없다",["大人でも難しいのだから、<b>まして</b>子どもには無理だ。","平日でも混んでいるのに、<b>ましてや</b>休日ともなれば<b>なおさらだ</b>。"],[541]],["〜ますように","ますように","〜てほしいと願う（祈り）","~하기를, ~하게 해 주세요 (기원)",["寒い日が続きますので、どうかお体を大切に<b>されますように</b>。","明日の試合で、みんなが実力を出せます<b>ように</b>。","試験に合格でき<b>ますように</b>。"],[138]],["〜まで","まで","〜のような極端なものも","~까지, ~마저",["その映画は、ふだん泣かない父<b>まで</b>泣かせてしまった。","親友に<b>まで</b>裏切られるとは思わなかった。"],[542]],["〜までだ／〜までのことだ","までだ","①〜するだけだ（ほかに方法がなければ）　②ただ〜しただけだ","①~하면 그만이다, ~할 뿐이다　②그저 ~했을 뿐이다",["私は事実を言った<b>まで</b>で、彼を責めるつもりはなかった。","この方法でうまくいかなければ、また一から考え直す<b>までだ</b>。","一度で合格できなければ、もう一度挑戦する<b>までだ</b>。"],[83]],["〜までに至らない","までにいたらない","〜という段階まではいかない","~하기까지는 이르지 않다",["幸い、けがは入院する<b>までには至らなかった</b>。","話し合いは続いているが、まだ合意する<b>までには至っていない</b>。"],[544]],["〜までになる","までになる","（努力などの結果）〜という程度になる","~할 정도가 되다, ~하기에 이르다",["彼は練習を重ね、全国大会に出場する<b>までになった</b>。","一年間勉強して、日本語で新聞が読める<b>までになった</b>。"],[545]],["〜までもない／〜までもなく","までもない","〜する必要はない","~할 것까지도 없다 / ~할 것도 없이",["わざわざ説明する<b>までもなく</b>、彼はすべてを理解していた。","駅はすぐそこだから、タクシーに乗る<b>までもない</b>。","健康のために睡眠が大切なのは、言う<b>までもない</b>。"],[108]],["〜まま（に）","まま","〜のとおりに・〜に任せて","~하는 대로",["店員に勧められる<b>まま</b>、高いコートを買ってしまった。","友人に誘われる<b>ままに</b>、そのサークルに入った。","足の向く<b>まま</b>、知らない町を歩いた。"],[225]],["〜まみれ","まみれ","〜がいっぱいついて汚れている","~투성이",["整備士は油<b>まみれ</b>になりながら、エンジンを修理した。","借金<b>まみれ</b>の生活から抜け出すために、必死に働いた。","雨の中で試合をして、選手たちは泥<b>まみれ</b>になった。"],[94]],["まるで〜ない","まるでない","まったく〜ない","전혀 ~않다",["兄は料理には<b>まるで</b>興味が<b>ない</b>。","何を言っているのか、<b>まるで</b>わから<b>ない</b>。"],[546]],["〜みたい（だ）","みたい","〜ようだ（話し言葉）","~인 것 같다",["外が騒がしいね。何か事故があった<b>みたい</b>。","彼は今日、元気がない<b>みたいだ</b>。"],[548]],["〜みたいに","みたいに","〜のように（話し言葉）","~처럼, ~같이",["今日は春<b>みたいに</b>暖かい。","彼女は子ども<b>みたいに</b>よく笑う。"],[549]],["〜めく／〜めいた","めく","〜らしくなる・〜のような感じがする","~다워지다 / ~같은, ~조의",["庭の梅がほころび始め、日差しもようやく春<b>めいて</b>きた。","上司の言葉には、どこか脅し<b>めいた</b>響きがあった。","彼は冗談<b>めいた</b>口調で、本音を語った。"],[109]],["〜もかまわず","もかまわず","〜を気にしないで","~도 아랑곳하지 않고, ~에도 개의치 않고",["子どもは服が汚れるの<b>もかまわず</b>、泥の中で遊んでいる。","彼女は人目<b>もかまわず</b>、大声で泣いた。"],[552]],["〜もさることながら","もさることながら","〜もそうだが、それ以上に","~도 그렇지만, ~은 물론이거니와",["この店は味<b>もさることながら</b>、店員の対応もすばらしい。","成功するには、才能<b>もさることながら</b>、努力が欠かせない。","彼女は歌唱力<b>もさることながら</b>、ダンスの技術も素晴らしい。"],[9]],["〜もしないうちに（うちから）","もしないうちに","まだ〜していないのに、もう","~하기도 전에",["息子は宿題を始め<b>もしないうちから</b>、遊びに行くことばかり考えている。","食べ終わり<b>もしないうちに</b>、もう次の料理が運ばれてきた。"],[553]],["〜もしないで／〜もせずに","もしないで","〜さえしないで","~하지도 않고",["説明書を読み<b>もしないで</b>、壊れたと言うのはおかしい。","彼はろくに調べ<b>もしないで</b>、無理だと決めつけた。","その犬は、大きな音がしても驚き<b>も</b>騒ぎ<b>もしない</b>。"],[139]],["AもAだ（が、BもBだ）","もだ","Aにも悪いところがある","~도 ~다 (~도 문제가 있다)",["約束を破った彼も彼だが、それを簡単に信じた私<b>も</b>私<b>だ</b>。","遅刻した彼も悪いが、確認しなかった<b>君も君だ</b>よ。"],[554,555]],["〜も同然だ","もどうぜんだ","ほとんど〜と同じだ","~나 마찬가지다, ~나 다름없다",["契約書にサインをもらえば、この仕事は成功した<b>も同然だ</b>。","あとは色を塗るだけだから、この絵は完成した<b>も同然だ</b>。"],[310]],["〜も〜ないも","もないも","〜するかしないかは","~하고 말고는, ~하든 안 하든",["留学する<b>もしないも</b>、最終的にはあなたが決めることだ。","合格する<b>もしないも</b>、これからの努力次第だ。"],[311]],["〜もの／〜もん","もの","〜から（理由・話し言葉）","~인걸(요), ~하니까",["今日は早く寝たいの。きのうあまり寝ていない<b>もの</b>。","だって、宿題が多すぎて遊ぶ時間がない<b>んだもん</b>。"],[312,560]],["〜ものか／〜もんか","ものか","絶対に〜ない","~할까 보냐, 절대 ~않는다",["こんな所でやめる<b>ものか</b>と、彼は最後まで走り続けた。","あんな店、二度と行く<b>もんか</b>。","あんな人に頼む<b>ものか</b>。自分の力でやってみせる。"],[313,558,561]],["〜ものがある","ものがある","〜という感じがする","~한 데가 있다, ~한 느낌이 있다",["この国の経済成長には、目を見張る<b>ものがある</b>。","故郷を離れる日の朝は、胸に迫る<b>ものがある</b>。","彼の演奏には、人の心を動かす<b>ものがある</b>。"],[226]],["〜ものだ","ものだ","①本当に〜だなあ（感動）　②〜するのが普通だ　③昔よく〜した","①(정말) ~하구나　②~하는 법이다　③~하곤 했다",["長年住んだ家を離れるのは、寂しい<b>ものだ</b>。","子どものころは、よくこの川で泳いだ<b>ものだ</b>。"],[557]],["〜ものと思われる","ものとおもわれる","〜だろうと考えられる","~할 것으로 생각된다, ~한 것으로 보인다",["台風の影響で、明日の便は欠航になる<b>ものと思われる</b>。","新しい薬は、来年には販売される<b>ものと思われる</b>。","この傾向は今後も続く<b>ものと思われる</b>。"],[227]],["〜ものとは思えない","ものとはおもえない","〜だとはとても考えられない","~라고는 도저히 생각할 수 없다",["このすばらしい絵が、子どもの描いた<b>ものとは思えない</b>。","この味は、とても素人が作った<b>ものとは思えない</b>。"],[559]],["〜ものなら","ものなら","もし〜できるなら（難しいが）","~할 수만 있다면",["子どものころに戻れる<b>ものなら</b>、もう一度やり直したい。","やり直せる<b>ものなら</b>、高校時代からやり直したい。","できる<b>ものなら</b>、もう一度学生時代に帰りたい。"],[167]],["〜ものの","ものの","〜けれども","~하기는 했지만, ~이지만",["新しいパソコンを買った<b>ものの</b>、使い方がよくわからない。","早起きしようと思った<b>ものの</b>、結局寝坊してしまった。","免許は取った<b>ものの</b>、まだ一人で運転するのは怖い。"],[124]],["〜ものを","ものを","〜のに（そうしなかったのが残念だ）","~했을 텐데, ~할 것을",["言ってくれれば手伝った<b>ものを</b>、どうして黙っていたの。","一言謝れ<b>ばよかったものを</b>、彼は最後まで言い訳を続けた。","黙っていればいい<b>ものを</b>、彼は余計なことを言って怒られた。"],[12]],["〜や／〜や否や","や","〜するとすぐに","~하자마자",["父は家に着く<b>や否や</b>、テレビをつけて野球を見始めた。","彼女はその知らせを聞く<b>や</b>、部屋を飛び出していった。","彼は席に着く<b>や否や</b>、パソコンを開いて仕事を始めた。"],[53]],["AやBといったN","やといった","AやBのようなN","~나 ~같은",["東京や大阪<b>といった</b>大都市では、家賃が高い。","この店では、すし<b>や</b>天ぷら<b>といった</b>日本料理が楽しめる。"],[314]],["〜（が）ゆえ（に）","ゆえ","〜が理由で","~때문에, ~(이)기에",["彼は若さ<b>ゆえに</b>、失敗を恐れずに挑戦することができた。","その美しさ<b>ゆえに</b>、この花は多くの人に愛されている。","責任ある立場である<b>がゆえに</b>、発言には注意が必要だ。"],[14]],["〜ようがない／〜ようもない","ようがない","〜する方法がない","~할 방법이 없다, ~할 수가 없다",["彼が無事に帰ってきたのは、奇跡としか<b>言いようがない</b>。","住所も電話番号もわからないので、連絡のし<b>ようもない</b>。","住所がわからないので、手紙の送り<b>ようがない</b>。"],[84,338]],["〜ようでは","ようでは","〜という状態では（よい結果にならない）","~해서는, ~하는 정도로는 (곤란하다)",["こんな簡単な問題が解けない<b>ようでは</b>、合格は難しい。","こんなことで泣いている<b>ようでは</b>、この先が思いやられる。","人の話を最後まで聞けない<b>ようでは</b>、リーダーは務まらない。"],[140]],["〜ような","ような","〜と同じくらいの・たとえば〜の","~같은, ~할 만한",["子どもが夢中になる<b>ような</b>楽しい絵本を作りたい。","涙が出る<b>ような</b>うれしい知らせが届いた。"],[562]],["〜ように","ように","①〜できるように（目的）　②〜しなさい（軽い命令・注意）","①~하도록, ~할 수 있게　②~하도록 (하세요)",["後ろの席の人にも聞こえる<b>ように</b>、大きな声で話してください。","お年寄りにも読める<b>ように</b>、字を大きくした。","廊下は走らない<b>ように</b>。"],[192]],["〜ようによっては","ようによっては","〜の方法しだいでは","~하기에 따라서는",["言い<b>ようによっては</b>、相手を傷つけずに断ることもできる。","考え<b>ようによっては</b>、今回の失敗も良い経験だったと言える。"],[315]],["〜ようもある","ようもある","〜する方法がある","~할 방법도 있다",["材料がそろえば、もっとおいしく作り<b>ようもある</b>のだが。","事前に相談してくれれば、何とかし<b>ようもあった</b>のに。"],[316]],["〜らしい","らしい","〜ようだ（聞いたこと・様子から）","~인 것 같다, ~라고 한다",["隣の部屋から笑い声が聞こえてきた。誰か客が来ている<b>らしかった</b>。","部長の機嫌がいいところを見ると、どうも交渉はうまくいった<b>らしい</b>。"],[317]],["〜わけです","わけです","〜ということです（説明・結論）","~인 것입니다, ~인 셈입니다",["毎日一時間練習しているのだから、上手になる<b>わけです</b>。","10年も日本に住んでいるんですか。それで日本語が上手な<b>わけです</b>ね。"],[564]],["〜わけではない","わけではない","全部が〜とは言えない","~인 것은 아니다",["嫌いな<b>わけではない</b>が、甘いものはあまり食べない。","値段の高い店がいつもおいしい<b>わけではない</b>。"],[229]],["〜わけにもいかない","わけにもいかない","（事情があって）〜することもできない","~할 수도 없다",["約束したので、今更断る<b>わけにもいかない</b>。","熱があったが、大事な会議なので休む<b>わけにもいかず</b>、出社した。","頼まれたので、断る<b>わけにもいかず</b>引き受けた。"],[230]],["〜を受けて","をうけて","〜に応じて・〜の影響で","~을 받아(들여), ~에 따라",["台風の接近<b>を受けて</b>、多くの学校が休校を決めた。","住民からの苦情<b>を受けて</b>、市は駅前の駐輪場を増やすことにした。","住民の要望<b>を受けて</b>、市は公園の整備を決めた。"],[125]],["〜をおいて（ほかに〜ない）","をおいて","〜以外に（ない）","~말고는 (없다), ~을 제외하고는",["このプロジェクトのリーダーは、彼<b>をおいて</b>他にいない。","この仕事を頼めるのは、あなた<b>をおいて</b>ほかにいません。","新鮮な魚を味わうなら、この港町<b>をおいて</b>ほかにはない。"],[22]],["〜をおして","をおして","（病気・反対など）を無理に乗り越えて","~을 무릅쓰고",["監督は体調不良<b>をおして</b>、最後まで試合の指揮をとった。","父は足の痛み<b>をおして</b>、私の結婚式に出席してくれた。","彼女は家族の反対<b>をおして</b>、一人で海外に留学した。"],[168]],["〜を思って","をおもって","〜のことを大切に考えて","~을 생각해서",["先生が厳しく叱ったのは、生徒のため<b>を思って</b>のことだ。","将来<b>を思って</b>、今から少しずつ貯金をしている。"],[565]],["〜を限りに","をかぎりに","〜を最後に","~을 끝으로",["今年度<b>を限りに</b>、この路線は廃止されることになった。","彼は今シーズン<b>を限りに</b>、現役を引退すると発表した。","山で道に迷った彼は、声<b>をかぎりに</b>助けを呼んだ。"],[54]],["〜を皮切りに（して）／〜を皮切りとして","をかわきりに","〜を始まりとして（次々に）","~을 시작으로",["東京公演<b>を皮切りに</b>、全国各地でコンサートが開かれる。","新製品はアジア<b>を皮切りに</b>、世界各地で発売される予定だ。","この会社は新宿店を<b>かわきりに</b>、都内に次々と店舗を広げた。"],[55]],["〜を機に","をきに","〜をきっかけに","~을 계기로",["定年退職<b>を機に</b>、夫婦で田舎に移り住むことにした。","結婚<b>を機に</b>、仕事を辞めて田舎に引っ越した。","就職<b>を機に</b>、一人暮らしを始めた。"],[149]],["〜を禁じえない","をきんじえない","（気持ち）を抑えられない","~을 금할 수 없다",["戦争で家族を失った人々の話には、同情<b>を禁じえない</b>。","被災者の体験談を聞き、涙<b>を禁じ得なかった</b>。","彼のあまりに無責任な態度には、驚き<b>を禁じえない</b>。"],[110]],["〜を契機に","をけいきに","〜をきっかけに","~을 계기로",["留学<b>を契機に</b>、海外の文化に関心を持つようになった。","入院したこと<b>を契機に</b>、たばこをやめた。"],[231]],["〜を最後に","をさいごに","〜を最後として","~을 마지막으로",["その歌手は、昨夜のコンサート<b>を最後に</b>活動を休止した。","彼は昨年の大会<b>を最後に</b>、選手を引退した。"],[566]],["AをAで終わらせない","をでおわらせない","Aを、ただのAのままにしない","~을 ~으로 끝내지 않는다",["<b>夢を夢で終わらせない</b>ために、毎日少しずつ努力を続けている。","<b>失敗を失敗で終わらせない</b>ために、原因をよく考えよう。"],[567]],["AをBとする","をとする","AをBと決める・考える","~을 ~로 하다, ~로 삼다",["この大会では、15歳以上であること<b>を</b>参加の条件<b>とする</b>。","この会は、会員の交流<b>を</b>目的<b>とする</b>。"],[568]],["〜をはじめ（として）","をはじめ","〜を代表的な例として","~을 비롯하여",["この町には、城<b>をはじめ</b>、古い建物がたくさん残っている。","この大学には、中国<b>をはじめとして</b>、世界各国から留学生が集まっている。"],[569,570]],["〜を控えて","をひかえて","〜がもうすぐなので","~을 앞두고",["試験<b>を控えて</b>、学生たちは図書館で勉強している。","結婚式<b>を控えて</b>、彼女は毎日忙しそうだ。"],[571]],["〜をふまえて／〜をふまえた","をふまえて","〜をもとにして・考えに入れて","~을 바탕으로, ~을 감안하여",["前回の反省<b>をふまえて</b>、今年のイベントの計画を立てた。","今回のアンケート結果<b>を踏まえて</b>、サービスを改善する。","過去のデータ<b>をふまえて</b>、来年度の予算案を作成した。"],[126,572]],["〜を経て","をへて","〜を通って・〜の過程のあとで","~을 거쳐",["十年に及ぶ研究<b>を経て</b>、新しい薬がついに完成した。","厳しい審査<b>を経て</b>、彼の作品が最優秀賞に選ばれた。","彼は営業部長<b>を経て</b>、社長に就任した。"],[193]],["〜をめぐって","をめぐって","〜について（議論・争いが起こる）","~을 둘러싸고",["新しい空港の建設<b>をめぐって</b>、住民の意見が分かれている。","父の遺産<b>をめぐって</b>、兄弟が争っている。"],[573]],["〜を目的として","をもくてきとして","〜を目指して","~을 목적으로",["この講座は、地域の高齢者の健康づくり<b>を目的として</b>開かれている。","この調査は、利用者の意見を知ること<b>を目的として</b>行われた。"],[574]],["〜をもって","をもって","①〜で（手段・方法）　②〜で終わりにする","①~(으)로, ~로써　②~을 끝으로, ~부로",["定員に達したため、本日<b>をもって</b>申し込みを締め切ります。","本人確認は、運転免許証などの身分証明書<b>をもって</b>行います。","本書の発送<b>をもって</b>、当選の発表に代えさせていただきます。"],[5]],["〜をもってしても","をもってしても","〜を使っても（できない）","~으로도, ~을 가지고도",["最新の医療技術<b>をもってしても</b>、この病気を治すことは難しい。","彼の実力<b>をもってしても</b>、その試験には合格できなかった。"],[318]],["〜をものともせず（に）","をものともせず","（困難）に負けないで","~을 무릅쓰고, ~에 굴하지 않고",["彼らは激しい嵐を<b>ものともせず</b>、山頂を目指して進んだ。","彼女は周囲の批判<b>をものともせず</b>、自分の研究を続けた。","彼は足のけが<b>をものともせずに</b>、最後まで走り続けた。"],[17]],["〜を余儀なくされる／〜を余儀なくさせる","をよぎなくされる","しかたなく〜することになる／させる","어쩔 수 없이 ~하게 되다 / ~하게 만들다",["大雪のため、列車は運転の見合わせ<b>を余儀なくされた</b>。","台風の影響で、多くの便が欠航<b>を余儀なくされた</b>。","台風のため、イベントは中止<b>を余儀なくされた</b>。"],[74]],["〜をよそに","をよそに","〜を気にしないで","~을 아랑곳하지 않고",["親の心配<b>をよそに</b>、息子は毎晩遅くまで遊び歩いている。","周囲の心配<b>をよそに</b>、彼女は手術から一週間で仕事に戻った。","母の小言<b>をよそに</b>、弟は毎日ゲームばかりしている。"],[13]],["〜んがため（に）","んがため","（どうしても）〜するために","~하기 위해서, ~하고자",["新記録を出さ<b>んがため</b>、彼は毎朝欠かさず練習している。","試合に<b>勝たんがため</b>に、彼らはどんな練習にも耐えた。","人気を得<b>んがための</b>発言は、すぐに見抜かれる。"],[62]],["〜んじゃなかった","んじゃなかった","〜しなければよかった（後悔）","~하는 게 아니었다, ~하지 말걸",["こんなにつまらない映画なら、見に来る<b>んじゃなかった</b>。","こんなに混むなら、車で来る<b>んじゃなかった</b>。"],[232]],["〜んだ","んだ","そうか、〜のか（わかって納得する）／事情の説明","~인 거구나, ~인 거야",["「駅前で事故があったらしいよ」「そうか。だから電車が遅れている<b>んだ</b>」","道が込んでいるね。事故があった<b>んだ</b>。"],[575]],["〜（る）んなら","んなら","〜するつもりなら（それなら）","~할 거라면",["駅に<b>行くんなら</b>、この手紙を出してきてくれる？","買い物に行く<b>んなら</b>、牛乳も買ってきて。"],[576]],["〜んばかりに／〜んばかりの／〜んばかりだ","んばかりに","今にも〜しそうな様子で","금방이라도 ~할 듯이",["店員は早く帰れと言わ<b>んばかりに</b>、閉店の準備を始めた。","合格の知らせを聞いて、妹は踊り出さ<b>んばかりに</b>喜んだ。","彼は「早く帰れ」と<b>言わんばかりに</b>時計を見た。"],[40]]]};
